(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0000.js"] = [{"id":"poem-e4067e5a","title":"登鹳雀楼","author":"王之涣","dynasty":"唐","verses":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"enabled":true,"collection":"内置精选","source":"原有内置录文；唐诗见《全唐诗》，苏轼词见《东坡乐府》。"},{"id":"poem-f707bda5","title":"旅夜书怀","author":"杜甫","dynasty":"唐","verses":["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章著，官应老病休。","飘飘何所似，天地一沙鸥。"],"enabled":true,"collection":"内置精选","source":"原有内置录文；唐诗见《全唐诗》，苏轼词见《东坡乐府》。"},{"id":"poem-0c732fc6","title":"念奴娇·赤壁怀古","author":"苏轼","dynasty":"宋","verses":["大江东去，浪淘尽，千古风流人物。","故垒西边，人道是，三国周郎赤壁。","乱石穿空，惊涛拍岸，卷起千堆雪。","江山如画，一时多少豪杰。","遥想公瑾当年，小乔初嫁了，雄姿英发。","羽扇纶巾，谈笑间，樯橹灰飞烟灭。","故国神游，多情应笑我，早生华发。","人生如梦，一尊还酹江月。"],"enabled":true,"collection":"内置精选","source":"原有内置录文；唐诗见《全唐诗》，苏轼词见《东坡乐府》。"},{"id":"poem-0003ddd76d83193d24306c25","title":"胡笳曲","author":"郑愔","dynasty":"唐","verses":["汉将留边朔，遥遥岁序深。","谁堪牧马思，正是胡笳吟。","曲断关山月，声悲雨雪阴。","传书问苏武，陵也独何心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fdda7097-88e0-4e31-8cd1-3a08d472d029","tags":[]},{"id":"poem-0007820eb149d196cc2df900","title":"狡童","author":"佚名","dynasty":"先秦","verses":["彼狡童兮，不与我言兮。维子之故，使我不能餐兮。","彼狡童兮，不与我食兮。维子之故，使我不能息兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-85","tags":[]},{"id":"poem-000f246acea1a61bfd91a463","title":"南乡子·袖敛鲛绡","author":"欧阳炯","dynasty":"五代","verses":["袖敛鲛绡，采香深洞笑相邀。","藤杖枝头芦酒滴，铺葵席，豆蔻花间趖晚日。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-6","tags":[]},{"id":"poem-0014245ccbdb82b277a7d462","title":"浊水求珠","author":"项斯","dynasty":"唐","verses":["灵魄自沉浮，从来任浊流。","愿从深处得，不向暗中投。","圆月时堪惜，沧波路可求。","沙寻龙窟远，泥访蚌津幽。","是宝终知贵，唯恩且用酬。","如能在公掌，的不负明眸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f6a6ca28-f855-499d-a11d-1dc886025960","tags":[]},{"id":"poem-00184e2566dac79cf4d24a2e","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑上］奴奴方始念弥陀，忽听堂前谁叫我。","偷睛把眼睃，却是我哥哥。","阿三，快把柴来烧焰火。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8185","tags":[]},{"id":"poem-0018570a4824f2666201b187","title":"哀江头","author":"杜甫","dynasty":"唐","verses":["少陵野老吞声哭，春日潜行曲江曲。","江头宫殿锁千门，细柳新蒲为谁绿。","忆昔霓旌下南苑，苑中万物生颜色。","昭阳殿里第一人，同辇随君侍君侧。","辇前才人带弓箭，白马嚼啮黄金勒。","翻身向天仰射云，一箭正坠双飞翼。","明眸皓齿今何在，血污游魂归不得。","清渭东流劒阁深，去住彼此无消息。","人生有情泪沾臆，江水江花岂终极。","黄昏胡骑尘满城，欲往城南忘南北。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8474f5c4-d18e-4b42-9702-19ad909b9ea2","tags":["唐诗三百首","描写水","爱国","伤怀","乐府","新乐府辞","写水"]},{"id":"poem-001d67a0556bff585ebaaa67","title":"临江仙·霜拍井梧干叶堕","author":"孙光宪","dynasty":"五代","verses":["霜拍井梧干叶堕，翠帷雕槛初寒。","薄铅残黛称花冠，含情无语，延伫倚栏干。","杳杳征轮何处去，离愁别恨千般。","不堪心绪正多端，镜奁长掩，无意对孤鸾。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-14","tags":[]},{"id":"poem-00252f90a2455c1ef00bfcf8","title":"渔父词・渔父·远水无涯山有邻","author":"赵构","dynasty":"宋","verses":["远水无涯山有邻。","相看岁晚更情亲。","笛里月，酒中身。","举头无我一般人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-222","tags":[]},{"id":"poem-0028f52b4c7552bad33672ef","title":"咏扇","author":"徐夤","dynasty":"唐","verses":["为发凉飙满玉堂，每亲襟袖便难忘。","霜浓雪暗知何在，道契时来忽自扬。","曾伴一樽临小槛，几遮残日过回廊。","汉宫如有秋风起，谁信班姬泪数行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-742f5e6f-b1eb-46d0-b3c7-e530d3aac46d","tags":[]},{"id":"poem-002a11f8c8685f6b3c044352","title":"浣溪沙·晚起红房醉欲消","author":"毛熙震","dynasty":"五代","verses":["晚起红房醉欲消，绿鬟云散袅金翘，雪香花语不胜娇。","好是向人柔弱处，玉纤时急绣裙腰，春心牵惹转无聊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-35","tags":[]},{"id":"poem-002dc1e8ddb33c32a13e3fb9","title":"送马廿七秀才归小枯村","author":"宋伯仁","dynasty":"宋","verses":["轻轻飞絮扑花枝，喜傍兰亭说旧诗。","君去小枯应为我，细看山带晚晴时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-08202a99-6d06-4ef5-b8a9-c4d77ee38048","tags":[]},{"id":"poem-003381ff1f5077848a0de074","title":"隋宫","author":"鲍溶","dynasty":"唐","verses":["柳塘烟起日西斜，竹浦风回鴈弄沙。","炀帝春游古城在，坏宫芳草满人家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d1c9f3a0-edb7-4a12-9ff5-b20468b1d296","tags":[]},{"id":"poem-003a2d0fd85b04505eae8f31","title":"月宫春·水晶宫里桂花开","author":"毛文锡","dynasty":"五代","verses":["水晶宫里桂花开，神仙探几回。","红芳金蕊绣重台，低倾玛瑙杯。","玉兔银蟾争夺护，嫦娥姹女戏相偎。","遥听钧天九奏，玉皇亲看来。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-25","tags":[]},{"id":"poem-0040619a20f3b7ce68527490","title":"四门子","author":"杨景贤","dynasty":"元","verses":["箕水豹斑斓隐雾端，壁水犭俞紧把眉攒，参水猿左右听呼唤。","水势溶宽，山高下不分匠段，路迢遥不见林峦。","水部雄火焰消迷路平安，十万里程受苦酸。","师父力多般，餐风宿露忙投窜。","宵衣旰食无撺断，受驱驰百万端。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2358","tags":[]},{"id":"poem-00431e177548b418f915aa89","title":"夜上受降城闻笛","author":"李益","dynasty":"唐","verses":["回乐峰前沙似雪，受降城下月如霜。","不知何处吹芦管，一夜征人尽望乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-992df222-c445-4925-a656-0caa4447d5bb","tags":["唐诗三百首","思念","战争","冬天","边塞","七言绝句","月亮"]},{"id":"poem-0071e7768b8dc4bc253720d3","title":"赤枣子·风淅淅","author":"纳兰性德","dynasty":"清","verses":["风淅淅，雨纤纤。","难怪春愁细细添。","记不分明疑是梦，梦来还隔一重帘。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-131","tags":[]},{"id":"poem-0073d228e46c8e3d7feaeafa","title":"鱼戏动新荷","author":"华镇","dynasty":"宋","verses":["风日向清和，游鱼水面多。","逶迤浮巨壑，摇漾动新荷。","密倚纤茄转，轻翻绿影俄。","参差吹弱藻，潋滟起微波。","跃跃同盈沼，洋洋类舞河。","因知濠上意，不羡越溪歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d27f8b30-f4f9-4fa1-8560-2388b9dfa5db","tags":[]},{"id":"poem-0076d3a58efbd1275880b221","title":"题故人所居","author":"佚名","dynasty":"唐","verses":["与君昔离别，星岁为三周；今日觏颜色，苍然双鬓秋。","茅居枕河浒，耕凿傍山丘。","往往登憇迳，时时或饭牛。","一身尚栖屑，庶身安无忧？","相见未言语，唏吁先泪流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4a28374b-df67-4c03-97b8-eb16bc314212","tags":[]},{"id":"poem-0077a8150ee06cb6ea6d8ac8","title":"永明山居诗（六十九首） 五十","author":"延寿","dynasty":"唐","verses":["得理元来行自成，万般情断一心冥。","樵人不到缘山僻，游客难逢为岳灵。","食蘖苦心何日就，看花醉眼几时醒。","索然身外无余物，云满前山水满瓶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e7f9157a-998a-467d-bc35-00a4bc8d7a1d","tags":[]},{"id":"poem-007881459b685525b20126fd","title":"徐提刑挽章","author":"释居简","dynasty":"宋","verses":["衣冠忽蜕尘，桃下是仙津。","身与吴天远，恩沾楚泽新。","授官宁后子，退己不先人。","尽是无私处，何慙第五伦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-95fe3d1d-0fdf-458c-97d6-f43f797f022e","tags":[]},{"id":"poem-00791e1fb9371cb7de3c62cd","title":"雁过沙","author":"徐田臣《杀狗记》","dynasty":"元","verses":["想爹娘养孙荣，抚养已艰辛，三年乳哺恩爱深，推干就湿多劳顿。","养儿长成，爹娘一命倾，痛思我父母珠泪零。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1846","tags":[]},{"id":"poem-007ad46cad4d87e4b374c5dc","title":"鹧鸪天·莫笑闲身老态多","author":"韩淲","dynasty":"宋","verses":["莫笑闲身老态多。","避人避世欲如何。","分明画出山阴道。","太息吟成宁戚歌。","穿木石，泛烟波。","从前魑魅喜人过。","灵山西畔高溪上，一棹归来舞短蓑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-463","tags":[]},{"id":"poem-007eb728085a324ea349cbe3","title":"行香子·黄金叶细","author":"杜安世","dynasty":"宋","verses":["黄金叶细，碧玉枝纤。","初暖日、当乍晴天。","向武昌溪畔，于彭泽门前。","陶潜影，张绪态，两相牵。","数株堤面，几树桥边。","嫩垂条、絮荡轻绵。","系长江舴艋，拂深院秋千。","寒食下，半和雨，半和烟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-915","tags":["长江"]},{"id":"poem-008839a2eff900b1d78a3a76","title":"减字木兰花·诗翁才刃","author":"黄庭坚","dynasty":"宋","verses":["诗翁才刃。","曾陷文场貔虎阵。","谁敢当哉。","况是焚舟决胜来。","三巴春杪。","客馆梦回风雨晓。","胸次峥嵘。","欲共涛头赤甲平。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-679","tags":[]},{"id":"poem-0089fbb5c8e82d5cf83458e1","title":"季冬送户部郎中使黔府选补","author":"卢僎","dynasty":"唐","verses":["握镜均荒服，分衡得大同。","征贤一台上，补吏五谿中。","雨露将天泽，文章播国风。","汉庭睽直谅，楚峡望清通。","马逐霜鸿渐，帆沿晓月空。","还期凤池拜，照耀列星宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1f345258-084a-43db-99a7-d8dd716b8c7f","tags":[]},{"id":"poem-008fc4d3474689a64c9ad2a9","title":"惜别","author":"李咸用","dynasty":"唐","verses":["细雨妆行色，霏霏入户来。","须知相识喜，却是别愁媒。","白刃方盈国，黄金不上台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-489d38f5-329b-4627-a6e1-8c521ae187a6","tags":[]},{"id":"poem-009b9aaf9af6a552cacfd553","title":"宿业师山房期丁大不至","author":"孟浩然","dynasty":"唐","verses":["夕阳度西岭，群壑倏已暝。","松月生夜凉，风泉满清听。","樵人归欲尽，烟鸟栖初定。","之子期宿来，孤琴候萝迳。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3e504df9-b22d-480e-9e7c-9f8ab8591b91","tags":["唐诗三百首","五言古诗","写景"]},{"id":"poem-00a174ac29bc01dadaf37cfc","title":"永明山居诗（六十九首） 二十四","author":"延寿","dynasty":"唐","verses":["危岭如登百尺楼，千般异景望中收。","浮生但向忙时过，万事须从静处休。","道直岂教容鬼怪，理平唯只使魔愁。","空门莫说无知己，满目松萝是我俦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d47fdce6-83b9-46c9-9254-0813e45af7af","tags":[]},{"id":"poem-00a20f715e2f7f328df24ec7","title":"萧宅二三子赠答诗二十首 客荅石","author":"卢仝","dynasty":"唐","verses":["遍索天地间，彼此最痴癖。","主人幸未来，与君为莫逆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c1177d8e-a46f-48f9-b280-bc2b6179f59e","tags":[]},{"id":"poem-00b0e52b9c06d5279f38d9a7","title":"倪文举寺簿挽诗三首  其三","author":"曾协","dynasty":"宋","verses":["水国相从日，文场并进时。","驽材元有限，逸驾自难追。","方指青云路，俄闻薤露诗。","鹏程千万里，却付称家儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a939c921-3f8a-4f5e-8e87-418e586ec500","tags":[]},{"id":"poem-00b481fafcbd05f7283fcf44","title":"送人归新罗","author":"贯休","dynasty":"唐","verses":["昨夜西风起，送君归故乡。","积愁穷地角，见日上扶桑。","蜃气生初霁，潮痕匝乱荒。","从兹头各白，魂梦一相望。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f8dc1637-e7f7-4982-9936-b45d4e44e459","tags":[]},{"id":"poem-00b7a876e622c8fc598c8d98","title":"越恁好","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)自上长安道，自上长安道，步蟾宫，挂紫袍。","为不就万俟丞相宠招，不从赘配多娇。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8355","tags":[]},{"id":"poem-00b96692a6251ccc3870b797","title":"郊庙歌辞 雩祀乐章 豫和","author":"不详","dynasty":"唐","verses":["鸟纬迁序，龙星见辰。","纯阳在律，明德崇禋。","五方降帝，万宇安人。","恭以致享，肃以迎神。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b6d6aed8-06a1-48c8-b0b8-d964e1b899ca","tags":[]},{"id":"poem-00ced67491069dc2465ecc51","title":"至潭州闻猿","author":"李绅","dynasty":"唐","verses":["昔陪天上三清客，今作端州万里人。","湘浦更闻猿夜啸，断肠无泪可沾巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7cd11d7f-d466-4ae5-8bc6-b23c8f676f1e","tags":[]},{"id":"poem-00cfb0ee0d6b6355c9eefc70","title":"鼓吹曲辞 有所思","author":"卢仝","dynasty":"唐","verses":["当时我醉美人家，美人颜色娇如花。","今日美人弃我去，青楼珠箔天之涯。","天涯娟娟常娥月，三五二八盈又缺。","翠眉蝉鬓生别离，一望不见心断绝。","心断绝，几千里，梦中醉卧巫山云。","觉来泪滴湘江水，湘江两岸花木深。","美人不见愁人心，含愁更奏绿绮琴，调高弦绝无知音。","美人兮美人！不知为暮雨兮为朝云。","相思一夜梅花发，忽到窗前疑是君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b9629e5e-c8bc-47e6-ae9f-2eba96a7fbda","tags":["爱情"]},{"id":"poem-00ddb90203d75baf265b6a24","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["心荒步紧，想着皇恩，已到寒门。","披袍秉笏更垂绅，冠和帔，一番新。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5278","tags":[]},{"id":"poem-00e84ba651e9db274470512a","title":"鹧鸪天·两个鸳鸯波上来","author":"向子𬤇","dynasty":"宋","verses":["两个鸳鸯波上来。","一ь杨柳掌中回。","已愁共雪因风去，更着繁弦急管催。","含浅笑，劝深杯。","桃花气暖眼边开。","司空常见风流惯，输与山翁醉玉摧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-102","tags":[]},{"id":"poem-00ed18dce48a0e789cdc314b","title":"郊庙歌辞 封泰山乐章 豫和 四","author":"张说","dynasty":"唐","verses":["高在上，道光明。","物资始，德难名。","承眷命，牧苍生。","寰宇谧，太阶平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fd353d00-a484-4bb1-a4d7-e595fac0ea52","tags":["泰山"]},{"id":"poem-00fd7d2dfa3282bf3c6e4f95","title":"摽有梅","author":"佚名","dynasty":"先秦","verses":["摽有梅，其实七兮。求我庶士，迨其吉兮。","摽有梅，其实三兮。求我庶士，迨其今兮。","摽有梅，顷筐塈之。求我庶士，迨其谓之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-19","tags":[]},{"id":"poem-0109060c1071e841813cd94e","title":"满庭芳","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［生上］乐守清贫，恭承严训，十年灯火相亲。","胸藏星斗，笔阵扫千军。","若遇桃花浪暖，定还我一跃龙门。","亲年迈，且自温衾扇枕，随分度朝昏。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8020","tags":[]},{"id":"poem-010f856b65134e133aa5a1dd","title":"善哉行 其三","author":"曹操","dynasty":"汉","verses":["朝日乐相乐，酣饮不知醉。","悲弦激新声，长笛吹清气。","弦歌感人肠，四坐皆欢悦。","寥寥高堂上，凉风入我室。","持满如不盈，有德者能卒。","君子多苦心，所愁不但一。","慊慊下白屋，吐握不可失。","众宾饱满归，主人苦不悉。","比翼翔云汉，罗者安所羁？","冲静得自然，荣华何足为！"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-20","tags":[]},{"id":"poem-0115161cbe9faf29ac97a1a3","title":"咸阳览古","author":"沈佺期","dynasty":"唐","verses":["咸阳秦帝居，千载坐盈虚。","版筑林光尽，坛场霤听疎。","野桥疑望日，山火类焚书。","唯有骊峰在，空闻厚葬余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-10b11d93-1d65-4449-bc10-24dc2494a5dd","tags":[]},{"id":"poem-0115711f7e9a2ea5e3e26788","title":"卜算子·不忍更回头","author":"黄童","dynasty":"宋","verses":["不忍更回头，别泪多于雨。","肺腑相看四十秋，奚止朝朝暮暮。","何事值花时，又是匆匆去。","过了阳关更向西，总是思兄处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-446","tags":[]},{"id":"poem-0116d11e8229688a7bfb80e8","title":"送杨皞东归","author":"卢纶","dynasty":"唐","verses":["登楼掩泣话归期，楚树荆云发远思。","日里扬帆闻戍鼓，舟中酹酒见山祠。","西江风浪何时尽，北客音书欲寄谁。","若说湓城杨司马，知君望国有新诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a7eef0a3-b6c6-41bf-9943-ac00dc60f57a","tags":[]},{"id":"poem-011bfd8cd408049057094d20","title":"客中行","author":"李白","dynasty":"唐","verses":["兰陵美酒郁金香，玉碗盛来琥珀光。","但使主人能醉客，不知何处是他乡。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-客中行","tags":[]},{"id":"poem-0129470cd8453499b9c4c7d6","title":"故南阳夫人樊氏挽歌","author":"王维","dynasty":"唐","verses":["石窌恩荣重，金吾车骑盛。","将朝每赠言，入室还相敬。","叠鼓秋城动，悬旌寒日映。","不言长不归，环珮犹将听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-44b2376c-e68d-4b0d-a57a-564d868445cc","tags":[]},{"id":"poem-01299437715382f6166d9cb6","title":"天柱隐所重荅江州应物","author":"畅当","dynasty":"唐","verses":["寂寞一怅望，秋风山景清。","此中惟草色，翻意见人行。","荒径饶松子，深萝绝鸟声。","阳崖全带日，宽嶂偶通耕。","拙昧难容世，贫寒别有情。","烦君琼玖赠，幽懒百无成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4f54d9c1-76d9-4cca-b20a-17b33225a457","tags":[]},{"id":"poem-012c6bdba2b05acb1b860fc2","title":"忆春日曲江宴后许至芙蓉园","author":"李绅","dynasty":"唐","verses":["春风上苑开桃李，诏许看花入御园。","香径草中回玉勒，凤皇池畔泛金樽。","绿丝垂柳遮风暗，红药低丛拂砌繁。","归绕曲江烟景晚，未央明月锁千门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f38153c7-0c90-4503-b578-f68aa067b156","tags":[]},{"id":"poem-01356399709a5b95ee3a27d7","title":"秋夜曲","author":"王涯","dynasty":"唐","verses":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1f66d2ec-8418-485e-a434-e21a0d439dda","tags":["思念","秋天","女子","唐诗三百首","乐府"]},{"id":"poem-0137b27273e9106a3fe84f10","title":"高宗皇帝挽词  其一","author":"林栗","dynasty":"宋","verses":["仓猝扶宗社，艰危启圣神。","英雄归驾御，狂狡愿和亲。","泛扫妖氛净，恢张治化新。","倦勤三纪外，头白尽遗民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f9147519-66e9-4ba2-b31b-a223098485a0","tags":[]},{"id":"poem-01385c8fee57231ca3c6a6bf","title":"渡江云·晴岚低楚甸","author":"周邦彦","dynasty":"宋","verses":["晴岚低楚甸，暖回雁翼，阵势起平沙。","骤惊春在眼，借问何时，委曲到山家。","涂香晕色，盛粉饰、争作妍华。","千万丝、陌头杨柳，渐渐可藏鸦。","堪嗟。","清江东注，画舸西流，指长安日下。","愁宴阑，风翻旗尾，潮溅乌纱。","今宵正对初弦月，傍水驿，深舣蒹葭。","沈恨处，时时自剔灯花。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-359","tags":[]},{"id":"poem-0139dae4dc6addac6de52f9f","title":"和张文裕初寒十首  其五","author":"司马光","dynasty":"宋","verses":["何处初寒好，初寒禹凿门。","遥天露崖口，轻浪漱山根。","万佛龛苔老，一灯林霭昏。","渔梁杳相望，石濑夜声喧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-697d1195-4c83-46a8-aa2c-ee7e40536d55","tags":[]},{"id":"poem-0146135cd8922708dcbd0940","title":"出云州书情寄两敕使","author":"王孝廉","dynasty":"唐","verses":["南风海路连归思，北雁长天引旅情。","赖有锵锵双鳯伴，莫愁多日住边亭。","（同前。","）（〖1〗按王孝廉奉渤海国王命使日，日本嵯峨天皇设宴礼之。","孝廉返国，舟覆溺海而死。","嵯峨天皇特颁敕书，追赠荣爵，且致悼念。","嵯峨在位十四年，年号曰弘仁，于唐则为宪宗元和五年至穆宗长庆三年也。","敕文附后。","〖2〗《日本后纪》二十四日本嵯峨天皇《赠渤海使王孝廉正三位敕书》云：「惜往饰终，事茂旧范，褒忠录绩，义存先彝。","故渤海国使从三位王孝廉，阙庭修聘，沧溟回舻，复命未申，昊苍不慭。","寔虽有命在天，薤露难驻，而衔恨使命，不得更归。","朕痛于怀，加赠荣爵，死而有灵，应业泉扃。","宜可正三位。","」〖3〗又日僧空海有《伤渤海国大使王孝廉中途物故》诗句，日人阪上今继有《和渤海大使见寄之作》，可以参阅。","诗附于次。","）（〖4〗空海《伤渤海国大使王孝廉中途物故》：一面新交不忍听，况乎乡国〖一作「园」〗故园〖一作「国」〗情。","〖见金毓黻撰《渤海国志长编》卷十八引《高野大师广传》下〗〖5〗阪上今继《和渤海大使见寄之作》：宾亭寂寞对青溪，处处登旅念凄。","万里云边辞国远，三春烟里望卿〖蒋礼鸿及陈九思同志并谓当是「乡」之形误。","〗迷。","长天去雁催归思，函谷来莺助客啼。","一面相逢如旧识，交情自与古人齐。","〖见金毓黻撰《渤海国志长编》卷十八引《文华秀丽集》上〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7d6020d8-ea72-4db2-bd58-e1dfda677b92","tags":[]},{"id":"poem-01553684b560d5bb029cb741","title":"陪幸长宁公主林亭","author":"萧至忠","dynasty":"唐","verses":["公主林亭地，清晨降玉舆。","画桥飞渡水，仙阁逈临虚。","新晴看蛱蝶，早夏摘芙蕖。","文酒娱游盛，忻叨侍从余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d9cc0940-aff6-4989-95d4-b7a780b0dc27","tags":[]},{"id":"poem-0158d83311d62e88c4b85eff","title":"归国遥·香玉","author":"温庭筠","dynasty":"唐","verses":["香玉，翠凤宝钗垂簏簌，胜金粟，越罗春水绿。","画堂照帘残烛，梦余更漏促。","谢娘无限心曲，晓屏山断续。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-20","tags":[]},{"id":"poem-015f1ba2e13dece6208ce6a8","title":"送黄构擢第后归江南","author":"孟郊","dynasty":"唐","verses":["澹澹沧海气，结成黄香才。","幼龄思奋飞，弱冠游灵台。","一鹗顾乔木，众禽不敢猜。","一骥骋长衢，众兽不敢陪。","遂得会风雨，感通如云雷。","至矣小宗伯，确乎心不回。","能令幽静人，声实喧九垓。","却忆江南道，祖筵花里开。","春风不能别，别罢空徘徊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-46adb3aa-63a6-4481-b0f9-842f35cb1edb","tags":[]},{"id":"poem-016198fcc3b7a0c48f03bba6","title":"醉乡春","author":"杨景贤","dynasty":"元","verses":["打渔鼓高歌兴添，采灵芝快乐无厌。","大叫高呼，前遮后掩。","远量度，近观瞻，谨廉礼谦，休猜我做避世陶潜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2341","tags":[]},{"id":"poem-01643cb04e3838691a731c9d","title":"汉宫春·黯黯离怀","author":"晁冲之","dynasty":"宋","verses":["黯黯离怀，向东门系马，南浦移舟。","薰风乱飞燕子，时下轻鸥。","无情渭水，问谁教、日日东流。","常是送、行人去后，烟波一向离愁。","回首旧游如梦，记踏青𣨼饮，拾翠狂游。","无端彩云易散，覆水难收。","风流未老，拚千金，重入扬州。","应又是、当年载酒，依前名占青楼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-658","tags":[]},{"id":"poem-01644052f5bad4dc13f7c9d8","title":"赠灵鹫山道润禅师院","author":"贯休","dynasty":"唐","verses":["常恨烟波隔，闻名二十年。","结为清气引，来到法堂前。","薪拾纷纷叶，茶烹滴滴泉。","莫嫌来又去，天道本泠然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4ad0983d-f474-4449-b5f0-e461259a328c","tags":[]},{"id":"poem-0167368eaa52075af2343de1","title":"水调歌头·九金增宋重","author":"毛滂","dynasty":"宋","verses":["九金增宋重，八玉变秦馀。","千年清浸，洗净河洛出图书。","一段升平光景，不但五星循轨，万点共连珠。","垂衣本神圣，补衮妙工夫。","朝元去，锵环佩，冷云衢。","芝房雅奏，仪凤矫首听笙竽。","天近黄麾仗晓，春早红鸾扇暖，迟日上金铺。","万岁南山色，不老对唐虞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-702","tags":[]},{"id":"poem-016f9ae790952da32308c36e","title":"百字令·宿汉儿村","author":"纳兰性德","dynasty":"清","verses":["无情野火，趁西风烧遍、天涯芳草。","榆塞重来冰雪里，冷入鬓丝吹老。","牧马长嘶，征笳乱动，并入愁怀抱。","定知今夕，庾郎瘦损多少。","便是脑满肠肥，尚难消受，此荒烟落照。","何况文园憔悴后，非复酒垆风调。","回乐峰寒，受降城远，梦向家山绕。","茫茫百感，凭高唯有清啸。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-159","tags":[]},{"id":"poem-0170326d92bb40524509acb2","title":"翠楼吟·月冷龙沙","author":"姜夔","dynasty":"宋","verses":["月冷龙沙，尘轻虎落，今年汉初赐。","新翻胡部曲，听毡幕、元戎歌吹。","层楼高峙。","看栏曲萦红，檐牙飞翠。","人姝丽。","粉香吹下，夜寒风细。","此地。","宜有词仙，拥素云黄鹤，与君游戏。","玉梯凝望久，叹芳草、萋萋千里。","天涯情味。","仗酒清愁，花销英气。","西山外。","晚来还卷，一帘秋霁。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-137","tags":["宋词三百首"]},{"id":"poem-0171b8eb1baefda25fbc5a42","title":"浪淘沙·深院绣帘垂","author":"毛滂","dynasty":"宋","verses":["深院绣帘垂。","前日春归。","画桥杨柳弄烟霏。","池面东风先解冻，龟上涟漪。","酒潋玉东西。","香暖狻猊。","远山郁秀入双眉。","待看碧桃花烂漫，春日迟迟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-863","tags":[]},{"id":"poem-017247dc1662ab6428a9abf9","title":"赠别二首 一","author":"杜牧","dynasty":"唐","verses":["娉娉褭褭十三余，豆蔻梢头二月初。","春风十里扬州路，卷上珠帘总不如。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-54008cd0-f9bf-424f-bc55-f15c1e9025f3","tags":["唐诗三百首"]},{"id":"poem-0177e693439a6391b2cc9193","title":"宿成都松溪院","author":"李洞","dynasty":"唐","verses":["松持节操溪澄性，一炷烟岚压寺隅。","翡翠鸟飞人不见，琉璃缾贮水疑无。","夜闻子落真山雨，晓汲波圆入画图。","尘拥蜀城抽锁后，此中犹梦在江湖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4f414440-934e-4b25-88db-4459ca7bcd36","tags":[]},{"id":"poem-018a551d1fc2876de5101518","title":"句  其二","author":"李昉","dynasty":"宋","verses":["微臣自愧头如雪，也向钧天侍玉皇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-cb0a8838-af6d-4170-bfcb-31d00785db5d","tags":[]},{"id":"poem-01a037211ed61faa5c029684","title":"和题丹景山至德寺","author":"蜀太妃徐氏","dynasty":"唐","verses":["丹景山头宿梵宫，玉轮金辂驻虚空。","军持无水注寒碧，兰若有花开晚红。","武士尽排青嶂下，内人皆在讲筵中。","我家帝子传王业，积善终期四海同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a7434702-2fb1-40ed-8ade-b3f21154f4d2","tags":[]},{"id":"poem-01a657d25a715fdbe92e6906","title":"观音大士赞","author":"释原妙","dynasty":"宋","verses":["大海波心，磐陀石上。","真观浄观，是相非相。","如月在天，无水不现。","水月俱捐，如何瞻仰。","咄，切忌妄想。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c3444ee5-e8b9-4afa-9691-e194730fb8ed","tags":[]},{"id":"poem-01afae83a12b67f6d2897411","title":"颂古七十六首  其一四","author":"释士珪","dynasty":"宋","verses":["江西一喝动乾坤，大用全机是灭门。","三日耳聋风过树，累他黄蘖丧儿孙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a37a9f44-970a-41e0-b50e-9f40322877bb","tags":[]},{"id":"poem-01b04ea0470d157c7c08b79e","title":"登衡山宿上封寺祝融峰","author":"柴元彪","dynasty":"宋","verses":["历井扪参上祝融，半空烟霭数声钟。","地连云汉九千丈，天柱东南七十重。","石磴悬崖翻瀑布，海门碾日上高峰。","翛然身世青冥表，俯立雷池看玉龙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b5d14e88-2951-4fc0-8923-da516ee57e9f","tags":["衡山"]},{"id":"poem-01b347a0b6894a8526b8ac31","title":"颂三首 三","author":"省澄","dynasty":"唐","verses":["吴坂当年塔未开，宋云葱岭见师回。","手携只履分明个，后代如何密荐来。","（见《祖堂集》卷十三。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-eab4fc15-2306-4cc8-b680-4912ca7f6b2d","tags":[]},{"id":"poem-01b45d0caad71aa2ead82c4a","title":"送夏侯审游蜀","author":"李端","dynasty":"唐","verses":["西望烟绵树，愁君上蜀时。","同林息商客，隔栈见罛师。","石滑羊肠险，山空杜宇悲。","琴心正幽怨，莫奏凤凰诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2fb33cc4-43fb-42b9-8e7e-2790d9a01d6b","tags":[]},{"id":"poem-01b9e11ef202210f003e9262","title":"送赵丞","author":"释居简","dynasty":"宋","verses":["归装又逐西凉去，轻省还如赴上时。","廉者固宜疎住计，富哉只有送行诗。","贴天自与鹓鸿举，钳纸谁容雁鹜欺。","它日宣城厅壁记，岿然一样斗山思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-82ca005e-548d-41da-877a-5ebd0adfa549","tags":[]},{"id":"poem-01c329bda110278d425c461d","title":"秋思","author":"陆游","dynasty":"宋","verses":["利欲驱人万火牛，江湖浪迹一沙鸥。","日长似岁闲方觉，事大如天醉亦休。","砧杵敲残深巷月，梧桐摇落故园秋。","欲舒老眼无高处，安得元龙百尺楼。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋思","tags":[]},{"id":"poem-01c74b698ad266c8c678d1e1","title":"投陈许崔尚书二十韵","author":"张祜","dynasty":"唐","verses":["重镇压华戎，恩威达圣聪。","泰山高不让，沧海阔难穷。","接物懽盈貌，安民术在衷。","旱天云出水，霜野鹗抟风。","东土承殊渥，南方著显功。","瑞呈须是鳯，畋获必非熊。","令下齐军仵，诗传入帝宫。","春行膏雨降，夜仰德星藂。","翰苑推词敏，台庭揖道崇。","才周儒学外，礼厚笑谭中。","吏理今廉度，文章昔马融。","行慿孤竹立，诺为一言终。","揭槛楼台耸，加笾海陆丰。","俯移青玉案，高挂绿沉弓。","大幕宾名瑀，长裾客姓冯。","耻为狂狷者，强厕滑稽雄。","马足虚行地，鞭头漫画空。","无能甘画虎，失趣奈雕虫。","死叹身何处，生嗟命不通。","聊当问詹尹，犹许诉明公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-bc87d881-d4b2-46a4-baa6-923814fddd96","tags":["泰山"]},{"id":"poem-01cf1069424adceacdc23d18","title":"醉花阴·帘卷西风轻雨外","author":"李弥逊","dynasty":"宋","verses":["帘卷西风轻雨外。","揖数峰横翠。","楼上地行仙，压玉为醪，旋摘黄金蕊。","一觞一阕千秋岁。","不愿封侯贵。","长伴紫髯翁，踏月吹箫，笑咏云山里。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-44","tags":[]},{"id":"poem-01d5d13a4ac7e64ad7d613e5","title":"奉和圣制送张尚书巡边","author":"袁晖","dynasty":"唐","verses":["出师宣九命，分阃用三台。","始应幕中画，言从天上来。","丹青不独任，韬略遂双该。","坐见威棱洽，弥彰事业恢。","旌旗晓云送，鞞鼓朔风催。","虏气消残月，边声韵落梅。","羽书雄北地，龙漠寝南垓。","宠战黄金尽，输诚白日回。","离章宸翰发，祖䜩国门开。","欲识恩华盛，平生文武材。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6100a4a9-5b27-4888-a917-ae59cb31c027","tags":[]},{"id":"poem-01d5f0251241cddb329ceb16","title":"宫词  其四○","author":"张公庠","dynasty":"宋","verses":["清晓传宣赐御题，日华初动露华晞。","集英殿上天香散，飞入千人白纻衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-34d6c006-5b75-48a3-a301-b5cb1676304f","tags":[]},{"id":"poem-01ebaa6a18915f7e4c666e05","title":"古别离","author":"皎然","dynasty":"唐","verses":["太湖三山口，吴王在时道。","寂寞千载心，无人见春草。","谁识缄怨者，持此伤怀抱。","孤舟畏狂风，一点宿烟岛。","望所思兮若何，月荡漾兮空波。","云离离兮北断，鸿眇眇兮南多。","身去兮天畔，心折兮湖岸。","春风胡为兮塞路，使我归梦兮撩乱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3c40a679-b659-4773-8737-7b37a226dcc3","tags":["太湖"]},{"id":"poem-01f469aee6c8ac3dfa846282","title":"绵搭絮","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["寻踪觅迹到江边。","李成舅，可曾带得香来？(末)小人不曾带得。","(老旦)我那儿，只一块香没福受用。","(苦)只得撮土为香，礼虽微，表姑情意怪。","望灵魂暂且听言：指望松萝相倚，谁想你抱石含冤？这也不要埋怨你丈夫，都是你的亲娘把乘龙女婿嫌。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8237","tags":[]},{"id":"poem-01fcf97174b7cf9cd67e0120","title":"次韵梁教章宰喜雪  其二","author":"陈造","dynasty":"宋","verses":["穷腊缺膏润，何异客病渴。","龙伯供雪事，落势不受遏。","缤纷一再余，旋报焦卷活。","去年痛无年，回首气尚夺。","流亡何纷纷，哀诉良聒聒。","为民倒陈红，拟效叫阍谒。","绣衣肉骨手，大帚扫妖孽。","贷金今可偿，复许岁再阅。","秦越作肥瘠，德人终不屑。","协气非挽回，何以救方割。","想闻三白讯，把酒颜为说。","嗣岁屈指计，老农聚头说。","团栾饱餠饦，市鬻追时节。","忍思狼狈初，草木茹根叶。","苦乐倚伏间，此耻幸一雪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-6c6e6624-f416-47f4-ad5f-8fec722a7e2d","tags":[]},{"id":"poem-02107a28972f3b9115998272","title":"辞世","author":"释原妙","dynasty":"宋","verses":["来不入死关，去不出死关。","铁蛇钻入海，撞倒须弥山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-cf20d89c-9844-4b2b-a818-4761266fc157","tags":[]},{"id":"poem-0215116bc07597a1c380c12b","title":"荅客","author":"鲍溶","dynasty":"唐","verses":["竹间深路马惊嘶，独入蓬门半似迷。","劳问圃人终岁事，桔槔声里雨春畦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8eb50ed6-2410-476b-b0f8-a9fea5df2db0","tags":[]},{"id":"poem-0235655785069b82ac28d53a","title":"崇法寺","author":"韩缜","dynasty":"宋","verses":["久闻云际山，中有古招提。","新秋喜远览，锐意穷攀跻。","出郭值微雨，凉风晓萋萋。","陂陀越大岭，沙路净无泥。","野沃稻田秀，耒耜沿沟畦。","登岑复入谷，渐过西山西。","举首望华屋，双岸鬰相携。","虚桥驾烟霭，峻闼排虹霓。","下马踏危级，褰裳涉修梯。","超然层阁外，仰视穹苍低。","俯眺亦何有，森森乔木齐。","喧嚣从吏语，嘲唽惊禽啼。","既饭复搜讨，林间得幽蹊。","岩阿访灵迹，大士常高栖。","古殿蚀苔藓，丹青暗尘㙠。","俯身践危蹬，侧足缘深溪。","老树阴潭黑，风修辞蝉嘶。","悬泉洗阴壁，莹色如玻瓈。","佳观诚可恋，迟留惧颠挤。","扪萝出天险，始免魂神睽。","缓步凌巀嵲，双旌随杖藜。","回瞻花雨地，已被烟云迷。","顿辔下平陆，晴川留马蹄。","新篁映碧宇，野寺临长堤。","乘倦驻归策，荒园步柔荑。","婆娑两高树，磊落垂红离。","汲井漱甘液，拂尘观旧题。","出门尚斜日，隐隐闻城鼙。","胜概亦陈迹，茫然失端倪。","为诗记仿佛，吾友无诃诋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-419dee11-7acb-44b1-a834-a38fd03f7de8","tags":[]},{"id":"poem-024182777504562c0e8ef378","title":"送侯秀才南游","author":"皎然","dynasty":"唐","verses":["芳草随君自有情，不关山色与猨声。","为看严子滩头石，曾忆题诗不著名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b6bfdacd-f332-425e-8612-db56bc69fbda","tags":[]},{"id":"poem-02467c7057fbf31c42f5c1f3","title":"别山居","author":"刘得仁","dynasty":"唐","verses":["万壑千岩景象开，登临未足又须回。","凭师莫断松间路，秋月圆时弟子来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3c776f78-a13c-49a8-bba2-68cbb50a7a83","tags":[]},{"id":"poem-024f903a28ddbbf433db49f4","title":"天衣怀禅师碑赞","author":"米芾","dynasty":"宋","verses":["稽首归依无上尊，清浄圆满千亿化。","三身俱现立法祖，一法不立即如来。","示现有渐缘慈悲，慈悲本不为佛祖。","佛祖不立无归依，所以三身开后觉。","寥寥千古古佛远，堂堂此身即古佛。","众生不昧本来心，此是古佛行住处。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4aa07514-e27a-433e-add3-793a93793c58","tags":[]},{"id":"poem-0254e30a7e905b1f1e74d452","title":"诉衷情·建章宫殿晚生寒","author":"曾觌","dynasty":"宋","verses":["建章宫殿晚生寒。","飞雪点朱阑。","舞腰缓随檀板，轻絮𣨼春闲。","愁思乱，酒肠悭。","漏将残。","玉人今夜，滴粉搓酥，应敛眉山。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-363","tags":[]},{"id":"poem-02574d0e3d729933b03e697f","title":"柳含烟·河桥柳","author":"毛文锡","dynasty":"五代","verses":["河桥柳，占芳春。","映水含烟拂路，几回攀折赠行人，暗伤神。","乐府吹为横笛曲，能使离肠断续。","不如移植在金门，近天恩。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-18","tags":[]},{"id":"poem-02582c3bce69913f2cce23df","title":"葛屦","author":"佚名","dynasty":"先秦","verses":["纠纠葛屦，可以履霜？掺掺女手，可以缝裳？要之襋之，好人服之。","好人提提，宛然左辟，佩其象揥。维是褊心，是以为刺。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-106","tags":[]},{"id":"poem-025e44c22bd7e16f151e56b6","title":"竹风亭","author":"释居简","dynasty":"宋","verses":["尽鉏菑翳了，华构绕筼筜。","矗矗半簷绿，疎疎六月凉。","雪林听响玉，粉节晕零霜。","话到杨州鹤，无非俗肺肠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-325bf593-4704-4cf8-96cb-db7c31c44f08","tags":[]},{"id":"poem-0262ccf4cb9b229b2150419c","title":"迎新春·嶰管变青律","author":"柳永","dynasty":"宋","verses":["嶰管变青律，帝里阳和新布。","晴景回轻煦。","庆嘉节、当三五。","列华灯、千门万户。","遍九陌、罗绮香风微度。","十里然绛树。","鳌山耸、喧天潇鼓。","渐天如水，素月当午。","香径里、绝缨掷果无数。","更阑烛影花阴下，少年人、往往奇遇。","太平时、朝野多欢民康阜。","随分良聚。","堪对此景，争忍独醒归去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-67","tags":[]},{"id":"poem-0263104898e0d1644a3ab216","title":"清明","author":"杜牧","dynasty":"唐","verses":["清明时节雨纷纷，路上行人欲断魂。","借问酒家何处有，牧童遥指杏花村。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-清明","tags":[]},{"id":"poem-026441bf0f25d829fe3684d6","title":"晚春","author":"韩愈","dynasty":"唐","verses":["草木知春不久归，百般红紫斗芳菲。","杨花榆荚无才思，惟解漫天作雪飞。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-晚春","tags":[]},{"id":"poem-026840f8b2ae1e79c54e9aea","title":"春光好·纱窗暖","author":"和凝","dynasty":"五代","verses":["纱窗暖，画屏间，亸云鬟。","睡起四肢无力，半春闲。","玉指剪裁罗胜，金盘点缀酥山。","窥宋深心无限事，小眉弯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-26","tags":[]},{"id":"poem-02689a22b03b83d58a9ad137","title":"雪中访别魏使君  其二","author":"释居简","dynasty":"宋","verses":["大雅离骚不入时，反骚变雅又奚为。","天台好处休提掇，只咏寒山拾得诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6b5398ef-b2dd-4b9e-a43e-9d9b5da6618a","tags":[]},{"id":"poem-026d8889298df62ca0e20078","title":"三会寺应制","author":"萧至忠","dynasty":"唐","verses":["岧嶤仓史台，敞朗绀园开。","戒旦壶人警，翻霜羽骑来。","下辇登三袭，褰旒望九垓。","林披馆陶牓，水浸昆明灰。","网户飞花缀，幡竿度鸟回。","豫游仙唱动，潇洒初尘埃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a138f221-c3fa-4f9c-be94-fb1cdffdf518","tags":[]},{"id":"poem-0277a48478bba35bc0f6ffac","title":"和李秀才雪中求酒","author":"徐铉","dynasty":"宋","verses":["雪英飘洒绕虚廊，晓景沉沉朔吹狂。","银阙晶荧标帝里，桂华纷糅认仙乡。","少年风味新吟动，老叟襟怀万事忘。","自倒空罇酬绝唱，书帏聊得泛寒光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c4a5111f-47dd-4ddd-815d-04e10a406c04","tags":[]},{"id":"poem-0278882c3eaa4f1558235765","title":"箫","author":"李峤","dynasty":"唐","verses":["虞舜调清管，王褒赋雅音。","参差横凤翼，搜索动猿吟。","灵鹤时来到，仙人幸见寻。","为听杨柳曲，行役几伤心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e8a1acb9-a691-4f29-bc84-cb6cb9abe539","tags":[]},{"id":"poem-02801c49ea6def423c66d78c","title":"偈颂（幷序○序为南岳齐己撰） 二","author":"居遁","dynasty":"唐","verses":["学道先须且学贫，学贫贫后道方亲。","一朝体得成贫道，道用还如贫底人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-514663a9-8554-4bfd-98bd-fe1c82246387","tags":["衡山"]},{"id":"poem-02812c734b92a4762359aa7a","title":"古寺","author":"唐求","dynasty":"唐","verses":["路傍古时寺，寥落藏金容。","破塔有寒草，坏楼无晓钟。","乱纸失经偈，断碑分篆踪。","日暮月光吐，绕门千树松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4ab353c5-7e72-4011-9a4e-00d35924ed0d","tags":[]},{"id":"poem-0286976858b8cac4b0a2abfb","title":"渔阳将","author":"张籍","dynasty":"唐","verses":["塞深沙草白，都护领燕兵。","放火烧奚帐，分旗筑汉城。","下营看岭势，寻雪觉人行。","更向桑干北，擒生问碛名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-027a565a-ada3-4e75-a195-e2322d952375","tags":[]},{"id":"poem-028dcb2d1a6cf9cd3cce2025","title":"郡斋宴坐","author":"张公庠","dynasty":"宋","verses":["为州容散诞，真慰野人情。","撼膝禅初悟，摇头句未成。","试香秋院静，斗墨午窗明。","已有东归计，柴扉掩姓名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-57d97a1d-9338-4dfd-bdb0-aa53b03d58f5","tags":[]},{"id":"poem-029a2f44fb24e43733a1fade","title":"南乡子·卧稻雨馀收","author":"黄庭坚","dynasty":"宋","verses":["卧稻雨馀收。","处处游人簇远洲。","白发又扶红袖醉，戎州。","乱折黄花插满头。","青眼想风流。","画出西楼一帧秋。","还把去年欢意舞，梁洲。","塞雁西来特地愁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-715","tags":[]},{"id":"poem-029d954b0291f3982bf4d4c9","title":"山居诗  其二二","author":"释延寿","dynasty":"宋","verses":["且停多事莫矜夸，寂寞门中有道华。","隈岭静同猿窟宅，栽松闲共鹤生涯。","荣来祇爱添余禄，春过谁能悟落花。","唯有卧云尘外客，无思无虑老烟霞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6c7d4481-f68a-4c7d-90d3-881659c71c6a","tags":[]},{"id":"poem-029ea5fdab18584fbf880a1d","title":"深山逢老僧二首 二","author":"贯休","dynasty":"唐","verses":["山童貌顽名乞乞，放火烧畬采崖蜜。","担头何物带山香，一箩白蕈一箩栗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-76124fa1-0a96-470d-a832-8f0742278cd5","tags":[]},{"id":"poem-029f059a5ee176fa21c4cbdd","title":"荆南道中","author":"曹松","dynasty":"唐","verses":["十月荒郊雪气催，依稀愁色认阳台。","游秦分系三条烛，出楚心殊一寸灰。","高柳莫遮寒月落，空桑不放夜风廻。","如何住在猿声里，却被蝉吟引下来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-849ae158-1eb5-40e2-a2a8-6d57fcdec8b3","tags":[]},{"id":"poem-02a6409249c1d895919a5ff3","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(小旦)奴今拜贺椿萱，念奴家生居陋室微贱，想前世共结良缘非浅。","人妻美少年。","双双拜谢天。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8925","tags":[]},{"id":"poem-02b12801bd949852736f75ce","title":"登慈恩寺塔","author":"张乔","dynasty":"唐","verses":["窗户几层风，清凉碧落中。","世人来往别，烟景古今同。","列岫横秦断，长河极塞空。","斜阳越乡思，天末见归鸿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-41228ca3-85bf-46fb-8663-a5947e49d78a","tags":[]},{"id":"poem-02b33699edb7cd3e59302694","title":"送友入关","author":"李端","dynasty":"唐","verses":["闻君帝城去，西望一沾巾。","落日见秋草，暮年逢故人。","非才长作客，有命懒谋身。","近更婴衰疾，空思老汉滨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-afb2ce80-73ac-47b6-bc68-bbcb083c31a3","tags":[]},{"id":"poem-02b4961e19a67275540c9c69","title":"郊庙歌辞 享太庙乐章 金奏","author":"不详","dynasty":"唐","verses":["肃肃清庙，巍巍盛唐。","配天立极，累圣重光。","乐和管磬，礼备烝尝。","永惟来格，降福无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-15e0461a-bd33-4197-8613-4c7adffe3fdd","tags":[]},{"id":"poem-02b7e5b02b4289b843589240","title":"临江仙","author":"无名氏《张协状元》","dynasty":"元","verses":["庭院深沉日正永。","(净出接)杨花点点沾襟。","(丑)许多侍婢汝知音。","(末)梓州今一任，你去直夫人。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2692","tags":[]},{"id":"poem-02bffb959dc40905bc9935f5","title":"寄王密卿","author":"李端","dynasty":"唐","verses":["酒乐今年少，僧期近日频。","买山多为竹，卜宅不缘贫。","志业归初地，文章寄此身。","嵇康虽有病，犹得见情人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-cfa9216e-b1c0-459d-94c9-972427733c96","tags":[]},{"id":"poem-02ca323fdb046da5db81ef41","title":"清平乐·野花芳草","author":"韦庄","dynasty":"五代","verses":["野花芳草，寂寞关山道。","柳吐金丝莺语早，惆怅香闺暗老。","罗带悔结同心，独凭朱栏思深。","梦觉半床斜月，小窗风触鸣琴。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-46","tags":[]},{"id":"poem-02d3aaebf92e504f87160163","title":"后出塞五首 二","author":"杜甫","dynasty":"唐","verses":["朝进东门营，暮上河阳桥。","落日照大旗，马鸣风萧萧。","平沙列万幕，部伍各见招。","中天悬明月，令严夜寂寥。","悲笳数声动，壮士惨不骄。","借问大将谁，恐是霍嫖姚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0e981612-b3bb-4124-93a1-06e4abd82099","tags":[]},{"id":"poem-02d50c1b5ede4dbbc5d011c4","title":"西江月·楼上风生白羽","author":"陈师道","dynasty":"宋","verses":["楼上风生白羽，尊前笑出青春。","破红展翠恰如今。","把酒如何不饮。","绣幕灯深绿暗，画帘人语黄昏。","晚云将雨不成阴。","竹月风窗弄影。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-297","tags":[]},{"id":"poem-02d8b17c452a166f643f341e","title":"尾声","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)恩情岂比闲花草？(生)往常恨更长寂寥，今夜只愁天易晓。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2991","tags":[]},{"id":"poem-02e4f621d1cba4bdfb9cba09","title":"寻南溪常山道人隐居","author":"刘长卿","dynasty":"唐","verses":["一路经行处，莓苔见履痕。","白云依静渚，春草闭闲门。","过雨看松色，随山到水源。","溪花与禅意，相对亦忘言。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-04af557e-bac8-4fbf-92e7-d8a87fa11038","tags":["唐诗三百首","写景","五言律诗"]},{"id":"poem-02e6a5a8a9dd1421e7ae8f93","title":"画山水图荅大愚","author":"荆浩","dynasty":"唐","verses":["恣意纵横埽，峰峦次第成。","笔尖寒树瘦，墨澹野云轻。","岩石喷泉窄，山根到水平。","禅房时一展，兼称苦空情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cc0bdb14-572d-41d2-993e-925e8fb7d36e","tags":[]},{"id":"poem-02e9ec8eb3ce46c47361a13b","title":"临灭偈（题拟）","author":"契此","dynasty":"唐","verses":["弥勒真弥勒，分（《布袋和尚传》作「化」）身千百亿。","时时示时（《布袋和尚传》作「世」、《鸡肋编》卷中作「识世」）人，时人终（《鸡肋编》作「总」、《五灯会元》作「自」、《布袋和尚传》作「俱」）不识。","（以上诸首均见《景德传灯录》卷二十七、《五灯会元》卷二、《卍续藏》本《明州定应大师布袋和尚传》〖元人昙噩作〗。","）（按：《布袋和尚传》云此为其灭后作，末题九字云：「不得状吾相，此即是真。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0503f285-33c1-45e2-b97f-31c8265a3dbb","tags":[]},{"id":"poem-02ebef9ac5109b01244fd251","title":"杜陵贻杜牧侍御","author":"赵嘏","dynasty":"唐","verses":["紫陌尘多不可寻，南溪酒熟一披襟。","山高昼枕石床隐，泉落夜窗烟树深。","白首寻人嗟问计，青云无路觅知音。","唯君怀抱安如水，他日门墙许醉吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-baddcc92-7920-4b9b-946e-f44542a75daa","tags":[]},{"id":"poem-02edbceae729bb8d4056f33e","title":"铁骑儿","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末上)离门儿，离门儿心惊胆碎，步疾去如飞。","到城南破窑，了事便回归。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1911","tags":[]},{"id":"poem-02faced93051b7c02ab9d206","title":"示如法禅人  其一","author":"释原妙","dynasty":"宋","verses":["识得根源认得伊，全身犹堕在尘围。","纵然和座都掀倒，尚有烟霞遶翠微。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-96fb6de0-5ec4-439a-b0b0-6d816a88be7e","tags":[]},{"id":"poem-02fe57e783e97b433dbd7dfa","title":"画堂春·一生一代一双人","author":"纳兰性德","dynasty":"清","verses":["一生一代一双人，争教两处销魂。","相思相望不相亲，天为谁春。","浆向蓝桥易乞，药成碧海难奔。","若容相访饮牛津，相对忘贫。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-3","tags":[]},{"id":"poem-0311a2c37c0237a000bf5643","title":"上行杯·芳草灞陵春岸","author":"韦庄","dynasty":"五代","verses":["芳草灞陵春岸，柳烟深，满楼弦管，一曲离声肠寸断。","今日送君千万，红楼玉盘金镂盏，须劝珍重意，莫辞满。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-18","tags":[]},{"id":"poem-031828ef22931eb247872884","title":"冬景","author":"刘克庄","dynasty":"宋","verses":["晴窗早觉爱朝曦，竹外秋声渐作威。","命仆安排新暖阁，呼童熨贴旧寒衣。","叶浮嫩绿酒初熟，橙切香黄蟹正肥。","蓉菊满园皆可羡，赏心从此莫相违。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-冬景","tags":[]},{"id":"poem-031b5a0b0bba9d9d47be19a7","title":"芹斋诗","author":"林光朝","dynasty":"宋","verses":["春风芹下足迟留，白鸟平田忆旧游。","说尽轩裳还过眼，读残书卷复从头。","偶逢隐几何须问，不到投簪便拟休。","平世声名如皦日，欲将何地置巢由。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-03611d03-cebf-4b4f-a6df-1ddd14ba4e57","tags":[]},{"id":"poem-032b28eefd2928c90dc41e65","title":"清平乐·露花烟柳","author":"李邴","dynasty":"宋","verses":["露花烟柳。","春思浓如酒。","几阵狂风新雨后。","满地落红铺绣。","风流何处疏狂。","厌厌恨结柔肠。","又是危阑独倚，一川烟草斜阳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-990","tags":[]},{"id":"poem-0331277e4a2f81ec1fc18b7f","title":"喝火令·见晚情如旧","author":"黄庭坚","dynasty":"宋","verses":["见晚情如旧，交疏分已深。","舞时歌处动人心。","烟水数年魂梦，无处可追寻。","昨夜灯前见，重题汉上襟。","便愁云雨又难寻。","晓也星稀，晓也月西沈。","晓也雁行低度，不会寄芳音。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-805","tags":[]},{"id":"poem-03367c6c67808f3c00bf7a24","title":"忆平泉杂咏 忆野花","author":"李德裕","dynasty":"唐","verses":["虽游洛阳道，未识故园花。","晓忆东谿雪，晴思冠岭霞。","谷深兰色秀，村迥柳阴斜。","怅望龙门晚，谁知小隐家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-50586423-6e02-4ebe-a4a9-1897f6ebdb80","tags":[]},{"id":"poem-03425745d358827b4d9f4194","title":"再次韵  其一","author":"陈造","dynasty":"宋","verses":["咄咄嗟数奇，覤覤笑坐驰。","超然达观士，显晦用一机。","夫君抱器业，轩豁见奇姿。","付我舟一叶，缗丝漾清漪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b6f0cf35-3e2f-4609-b8b9-89b6a22a5a14","tags":[]},{"id":"poem-0345e863e88933ee05471a60","title":"大隐坊 赵记室俶在职无事","author":"孟郊","dynasty":"唐","verses":["卑静身后老，高动物先摧。","方圆水任器，刚劲木成灰。","大道母群物，达人腹众才。","时吟尧舜篇，心向无为开。","彼隐山万曲，我隐酒一杯。","公庭何所有，日日清风来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e2dd3fa6-35ad-47a2-bc87-9f4ce44faf33","tags":[]},{"id":"poem-0348f89b6e9816b59de1afa0","title":"汲斋吟","author":"王柏","dynasty":"宋","verses":["我有一泓水，清明如鉴开。","妍丑自来往，曾不留纤埃。","静而涵万古，动时濡九垓。","人与我同得，是名为灵台。","胡乃忍芜秽，漂沦良可哀。","当知克己如汲井，汲去污浊清自回。","洙泗渊源初不息，河洛流派空争猜。","为学工夫孰大此，莫翻波浪惊儿孩。","昌黎修绠志徒苦，瘦岛辘轳用未该。","请观朱子方塘喻，要识源头活水来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c7dbc68b-de61-4a3d-9797-bb63a840f6b3","tags":[]},{"id":"poem-0349a4333c6a583e93f0d1b2","title":"仲辅和寄送季弟诗复次韵寄之  其一","author":"李纲","dynasty":"宋","verses":["块处江城无与游，芦花枫叶楚天秋。","萧然霜鬓伤迟暮，久矣灰心任去留。","道阻每怀千里念，时危岂为一身忧。","何年棣蕚还相映，醉卧元龙百尺楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8d2902b8-f96b-4fc9-a057-179ad1dd62b5","tags":[]},{"id":"poem-034a2eee4b25f80ae271a1f7","title":"京山行","author":"孟郊","dynasty":"唐","verses":["众䖟聚病马，流血不得行。","后路起夜色，前山闻虎声。","此时游子心，百尺风中旌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c956cd69-5f68-45a2-bf67-ac8ff591f77c","tags":[]},{"id":"poem-034cf7973305c2601715e822","title":"闻官军收河南河北","author":"杜甫","dynasty":"唐","verses":["劒外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-22e90c0d-2b59-4500-8e5d-80d38ec4692c","tags":["唐诗三百首","七言律诗","思归","六年级下册","小学古诗"]},{"id":"poem-03585948cbc725b57947f4f7","title":"赠廖道士","author":"李涉","dynasty":"唐","verses":["膏已明煎信矣哉，二年人世不归来。","庭前为报仙桃树，今岁花时好好开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f8a77c24-880b-4d01-bfd0-4430f0f05579","tags":[]},{"id":"poem-0361c2b4ece9a3b2c25b71de","title":"采莲词","author":"赵崇嶓","dynasty":"宋","verses":["别浦潮生花梦寒，片红飞下粉痕干。","预知妾面如花面，泣向西风不忍看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-22590e4c-96c3-4b81-a137-bb378c6759c4","tags":[]},{"id":"poem-0365a32167ed3b698eba7397","title":"小师智广请赞","author":"释了惠","dynasty":"宋","verses":["泽广藏山，理能伏豹。","父既不慈，子亦不孝。","吉凶影象自分明，不用烧香求卦兆。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-075088b3-2e94-4808-bb9e-2c8fafd483d7","tags":[]},{"id":"poem-036fde436b1b55d6b31cef77","title":"冬日闲居遣兴十首  其五","author":"李纲","dynasty":"宋","verses":["宿雨乍晴天，初寒气暂暄。","梳头风满栉，曝背日临轩。","小酌无新酿，闲眠只旧毡。","忘心亦忘法，作个是安禅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f2d57015-0c18-44fe-a2f6-b6f58229f800","tags":[]},{"id":"poem-03791fe2816f5f294942c2b8","title":"生日客朱溪主人云今年乃青山真生日也感其语作诗自寿","author":"赵文","dynasty":"宋","verses":["人生难得真生日，正使百年才遇一。","我今客里值斯时，况复主人相款密。","连宵举酒为我寿，满眼鸡豚破梨栗。","寿牋投赠盛宾友，寿觞拜舞罗弟姪。","假今家居那有此，米盐纷纠费爬栉。","去年闽山收弟骨，日夜悲啼吟蟋蟀。","岁晚方能负骨归，此愿已偿甘似蜜。","平生苦遭儿女累，十年求解如沐漆。","今年二子各成婚，坐看明年婚嫁毕。","云边太史相邂逅，许我行年七十七。","盖棺以前日一诗，万首犹堪剑南匹。","未知先生竟肯否，不肯便问天公乞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f6e5075c-8a10-41ac-b527-a65337fe26e9","tags":[]},{"id":"poem-038b30602c080dd137d7d140","title":"清谿馆作","author":"谈戭","dynasty":"唐","verses":["指途清谿里，左右唯深林。","云蔽望乡处，雨愁为客心。","遇人多物役，听鸟时幽音。","何必沧浪水，庶兹浣尘襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-74b8473f-9ca2-436f-a3d7-cd0e4acfa909","tags":[]},{"id":"poem-038b36a2054eedf12c35f74f","title":"别谪者","author":"杨凝","dynasty":"唐","verses":["此地闻犹恶，人言是所之。","一家书绝久，孤驿梦成迟。","八月三湘道，闻猨冒雨时。","不须祠楚相，臣节转堪疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e4e287f1-f101-4d55-8448-1f73442ef2f5","tags":[]},{"id":"poem-03940255a5e11de0483d6978","title":"送权先辈归觐信安","author":"赵嘏","dynasty":"唐","verses":["衣彩独归去，一枝兰更香。","马嘶芳草渡，门掩百花塘。","野色亭台晚，滩声枕簟凉。","小斋松岛上，重叶覆书堂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-28a80f28-64e4-4523-87a2-73557f3d2650","tags":[]},{"id":"poem-03a0bfa8069b070c3e0700d7","title":"劒池","author":"李岘","dynasty":"唐","verses":["阖闾葬日劳人力，嬴政穿来役鬼功。","澄碧尚疑神物在，等闲雷雨起潭中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-8b49ae18-32e1-406a-be79-b882da27d61a","tags":[]},{"id":"poem-03b25556cefea2a268295d13","title":"答卢仝","author":"孟郊","dynasty":"唐","verses":["楚屈入水死，诗孟踏雪僵。","直气苟有存，死亦何所妨。","日劈高查牙，清棱含冰浆。","前古后古冰，与山气势强。","闪怪千石形，异状安可量。","有时春镜破，百道声飞扬。","潜仙不足言，朗客无隐肠。","为君倾海宇，日夕多文章。","天下岂无缘，此山雪昂藏。","烦君前致词，哀我老更狂。","狂歌不及狂，歌声缘凤皇。","凤兮何当来，消我孤直疮。","君文真凤声，宣隘满铿锵。","洛友零落尽，逮兹悲重伤。","独自奋异骨，将骑白角翔。","再三劝莫行，寒气有刀枪。","仰慙君子多，慎勿作芬芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-65bd4ccd-a4b5-489f-9cc9-d575d5ef735c","tags":[]},{"id":"poem-03c26b8cfe6bd19739b08523","title":"旧闻长沙城东梅坞甚盛近岁亦买园其间念欲一往未果也癸巳仲冬二十有八日始与客游过东屯渡十余里间玉雪弥望平时所未见也归而为诗以纪之","author":"张栻","dynasty":"宋","verses":["半生客荆楚，历览非一隅。","宁知城东路，有此梅万株。","瘦马路晓寒，清风起菰蒲。","度溪上平坂，顿觉景物殊。","霏雪下晴昼，香雾迷前驱。","近坡与远岭，玉立同一区。","老树固瑰特，小枝亦敷腴。","有如众君子，汇聚德不孤。","精粗无可拣，酥酪与醍醐。","千株未觉多，此语信不诬。","班荆或小憩，沽酒时一斟。","胜赏谅难尽，昭质知不渝。","我有十亩园，丘壑正盘纡。","念此缟袂侣，岁晚足我娱。","来游自今始，琴书与之俱。","回首桃李场，冷淡莫邪揄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-984ed0ef-8eda-461d-8644-d8e3b4825a38","tags":[]},{"id":"poem-03ce35548f1a271b388634a9","title":"秋夜对月怀李正封","author":"鲍溶","dynasty":"唐","verses":["援琴怅独立，高月对秋堂。","美人远于月，徒望空景光。","坐忆执手时，七弦起凄凉。","平生知音少，君子安可忘。","客意如梦寐，路岐遍四方。","日远迷所之，满天心暗伤。","主奉二鲤鱼，中含五文章。","惜无千金荅，愁思盈中肠。","此夕临风叹，零露沾衣裳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-43220e26-c586-418c-a20b-102a4536a4a0","tags":[]},{"id":"poem-03d11e11020a021ff598d52c","title":"夏云峰·天阔云高","author":"仲殊","dynasty":"宋","verses":["天阔云高，溪横水远。","晚日寒生轻晕。","闲阶静、杨花渐少，朱门掩、莺声犹嫩。","悔匆匆、过却清明，旋占得馀芳，已成幽恨。","都几日阴沈，连宵慵困。","起来韶华都尽。","怨入双眉闲斗损。","乍品得情怀，看承全近。","深深态、无非自许。","厌厌意、终羞人间。","争知道、梦里蓬莱，待忘了馀香，时传音信。","纵留得莺花，东风不住，也则眼前愁闷。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-107","tags":["宋词三百首"]},{"id":"poem-03e1452a8b40b8f2541e01d7","title":"九怀·通路","author":"王褒","dynasty":"汉","verses":["天门兮墬户，孰由兮贤者？","无正兮溷厕，怀德兮何睹？","假寐兮愍斯，谁可与兮寤语？","痛凤兮远逝，畜𫛩兮近处。","鲸鱏兮幽潜，从虾兮游陼。","乘虬兮登阳，载象兮上行。","朝发兮葱岭，夕至兮明光。","北饮兮飞泉，南采兮芝英。","宣游兮列宿，顺极兮彷徉。","红采兮骍衣，翠缥兮为裳。","舒佩兮𬘭𫄥，竦余剑兮干将。","腾蛇兮后从，飞駏兮步旁。","微观兮玄圃，览察兮瑶光。","启匮兮探䇲，悲命兮相当。","纫蕙兮永辞，将离兮所思。","浮云兮容与，道余兮何之？","远望兮仟眠，闻雷兮阗阗。","阴忧兮感余，惆怅兮自怜。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-39","tags":[]},{"id":"poem-03e4335f3bd9fbdb3b197248","title":"满江红·潇洒星郎","author":"赵老","dynasty":"宋","verses":["潇洒星郎，吹绿鬓、胜游霞举。","秋又半，月磨云翳，籁传风语。","太一青黎光对射，中流荡漾莲舟舞。","戏人间、今夜水精宫，前无古。","吾家是，蓬山侣。","歌舞袖，苹花渚。","拟问津斜汉，乘槎南浦。","谒帝通明今得便，素娥拍手心先许。","笑画阑、三十六宫秋，花如土。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-272","tags":[]},{"id":"poem-03f19fae95e8cb1095c38d46","title":"东湖赠僧子兰","author":"张乔","dynasty":"唐","verses":["名利了无时，何人暂访师。","道情闲外见，心地语来知。","竹落穿窗叶，松寒荫井枝。","匡山许同社，愿卜挂帆期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-03ce758a-99de-440d-aed3-dacab03880b9","tags":["庐山"]},{"id":"poem-03f2e27827671e5997f40a58","title":"道林寺","author":"裴说","dynasty":"唐","verses":["独立凭危阑，高低落照间。","寺分一派水，僧锁半房山。","对面浮世隔，垂帘到老闲。","烟云与尘土，寸步不相关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-237f07cc-729b-4af7-af21-cae00a44bf52","tags":[]},{"id":"poem-03f64c4d94dfb231f0988faa","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["有儿却遣他出去，教媳妇怎生区处？媳妇，可怜误你芳年纪。","(合前)(旦唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4996","tags":[]},{"id":"poem-03fb1454beabf79854ed0f63","title":"诉衷情·永夜抛人何处去","author":"顾敻","dynasty":"五代","verses":["永夜抛人何处去，绝来音。","香阁掩，眉敛，月将沉。","怎忍不相寻？鸳孤衾。","换我心为你心，始知相忆深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-20","tags":[]},{"id":"poem-0404ccd93d30fbc4cde3f747","title":"秋千","author":"僧惠洪","dynasty":"宋","verses":["画架双裁翠络偏，佳人春戏小楼前。","飘扬血色裙拖地，断送玉容人上天。","花皮润沾红杏雨，彩绳斜挂绿杨烟。","下来闲处从容立，疑是蟾宫谪神仙。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-鞦韆","tags":[]},{"id":"poem-041885d9","title":"迢迢牵牛星","author":"佚名","dynasty":"汉","verses":["迢迢牵牛星，皎皎河汉女。","纤纤擢素手，札札弄机杼。","终日不成章，泣涕零如雨。","河汉清且浅，相去复几许？","盈盈一水间，脉脉不得语。"],"enabled":true,"collection":"历代名篇","source":"《文选》卷二十九《古诗十九首》。","tags":["古诗十九首","相思"]},{"id":"poem-041d8ed7c5a4465f7b2ba3d0","title":"聂耒阳以仆阻水书致酒肉疗饥荒江诗得代怀兴尽本韵至县呈聂令陆路去方田驿四十里舟行一日时属江涨泊于方田","author":"杜甫","dynasty":"唐","verses":["耒阳驰尺素，见访荒江眇。","义士烈女家，风流吾贤绍。","昨见狄相孙，许公人伦表。","前期翰林后，屈迹县邑小。","知我碍湍涛，半旬获浩溔。","麾下杀元戎，湖边有飞旐。","孤舟增郁郁，僻路殊悄悄。","侧惊猿猱捷，仰羡鹳鹤矫。","礼过宰肥羊，愁当置清醥。","人非西喻蜀，兴在北坑赵。","方行郴岸静，未话长沙扰。","崔师乞已至，澧卒用矜少。","问罪消息真，开颜憩亭沼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d64eae7b-aed2-4cad-b8dc-26f8f7dca88d","tags":[]},{"id":"poem-04259e061df8e313e69d824a","title":"梦游仙四首 二","author":"贯休","dynasty":"唐","verses":["三四仙女儿，身著瑟瑟衣。","手把明月珠，打落金色梨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-edee2b50-743e-4c16-9bbd-38a933a1f9ae","tags":[]},{"id":"poem-043af48f263773819be3cdf1","title":"芄兰","author":"佚名","dynasty":"先秦","verses":["芄兰之支，童子佩觿。虽则佩觿，能不我知。容兮遂兮，垂带悸兮。","芄兰之叶，童子佩韘。虽则佩韘，能不我甲。容兮遂兮，垂带悸兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-59","tags":[]},{"id":"poem-044ca58ed17572427686a4f5","title":"马嵬坡","author":"郑畋","dynasty":"唐","verses":["[玄]宗回马杨妃死，云雨虽亡日月新。","终是圣明天子事，景阳宫井又何人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7e75853a-bf7a-4d8d-b3e9-0537f4ed913a","tags":["唐诗三百首","七言绝句","带有地名","咏史","地名"]},{"id":"poem-044f6f9046b4559ff3387b2b","title":"渔家傲·侍宴乐游游赏惯","author":"洪皓","dynasty":"宋","verses":["侍宴乐游游赏惯。","今兹吊影难呼伴。","欲上望乡台复倦。","愁满眼。","琵琶莫写昭君怨。","满目平芜无足玩。","南冠未税徒增欢。","万里庭闱安否断。","形魂散。","此身何暇穷游观。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-912","tags":[]},{"id":"poem-045530eed8b1567f1e5fa2b5","title":"塞上听弹胡笳作（幷序）","author":"李昂","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cdfe174e-7592-4beb-a924-6c1ced36f433","tags":[]},{"id":"poem-0455a41abc759aa3b23ef94f","title":"送沈先辈尉昭应","author":"张乔","dynasty":"唐","verses":["余才不废诗，佐邑喜闲司。","丹陛终须去，青山未可期。","叶凋温谷晚，云出古宫迟。","若草东封疏，君王到有时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-590acf9b-de49-48bb-a074-102775ec44a0","tags":[]},{"id":"poem-0456bedb474bb5126c16cdc2","title":"颂古三十一首  其一一","author":"释玿","dynasty":"宋","verses":["当机转处不踌躇，琉璃盘里走明珠。","赵州老子村校书，一条拄杖两人舁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7bde5098-3c54-4308-8bef-2445653d7f41","tags":[]},{"id":"poem-04619f634346221db7c2ed09","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生)无非买命与赎身，但随行有何囊箧资费？(生、旦)没有，将军。","(众)快口强舌，休同儿戏。","(生、旦)听启，乱慌慌行来数日，苦滴滴实没半厘。","(众)你好不知礼。","常言道：\"打鱼猎射怎空回？\"。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2962","tags":[]},{"id":"poem-0461fa6c0a6e9c4b64f0cbe8","title":"敦煌廿咏（并序） 十七、望京门咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["郭门望京处，楼上启重𬮱。","水北通西域，桥东路入秦。","黄沙吐双径[三四]，白草生[三五]三春。","不见中华使，翩翩起虏尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-aeaf2ad5-abad-4d11-afbf-018e5f285f0e","tags":[]},{"id":"poem-046720588defcfe00282bc9b","title":"咏史诗 秦庭","author":"胡曾","dynasty":"唐","verses":["楚国君臣草莽间，吴王戈甲未东还。","包胥不动咸阳哭，争得秦兵出武关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-86e49eba-77e5-42c9-a1c2-90a2a2351936","tags":[]},{"id":"poem-046b85643d944f2ef52f1ef1","title":"乌程李明府水堂同卢使君幼平送奘上人游五台","author":"皎然","dynasty":"唐","verses":["身将刘令隐，经共谢公翻。","有此宗师在，应知我法存。","问心常寂乐，为别岂伤魂。","独访华泉去，秋风入雁门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-930f9898-6d9f-4812-b0f4-03a05b803b34","tags":[]},{"id":"poem-046dcc9c532341326789e8ae","title":"送李司空赴镇襄阳","author":"张籍","dynasty":"唐","verses":["中外兼权社稷臣，千官齐出拜行尘。","再调公鼎勋庸盛，三受兵符宠命新。","商路雪开旗斾展，楚堤梅发驿亭春。","襄阳风景由来好，重与江山作主人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b7768076-32f2-47d4-8e1e-18841709b67e","tags":[]},{"id":"poem-04724661380ab1a39d4b8539","title":"拟赋江南寄梅花诗","author":"王十朋","dynasty":"宋","verses":["蔚宗居垅首，陆凯在江南。","手折梅花寄，人逢驿使堪。","吴都寻半吐，楚岸摘新含。","雪里开才一，楼头弄未三。","情深殊折柳，意重胜题柑。","溪上千株玉，归欤待自探。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-38df726b-2c6b-45ce-81d1-4c76e9d22480","tags":[]},{"id":"poem-0478105050b6a1a12fb8206c","title":"游仙词三十三首  其三一","author":"王镃","dynasty":"宋","verses":["天花子落月中楼，香满三千世界秋。","下有老人常斫树，至今玉斧不曾修。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-876d9bf4-5079-44fc-9c3f-2ab1dc4da381","tags":[]},{"id":"poem-0482933c5cc10f0c2ed09975","title":"洛阳春望","author":"张祜","dynasty":"唐","verses":["世事空悲衰复荣，慿音一望更添情。","红颜只向爱中尽，芳草先从愁处生。","佳气蔼空迷鳯阙，绿杨抵水挠宫城。","（「挠」，严疑当作「绕」。","）游执行驻马烟花外，玉笛不利何处声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4351b470-b3b7-46a2-8329-1e450bac14bb","tags":[]},{"id":"poem-048d0a32206ee9d76f0da153","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)奴试听君说元因，心下添忧闷。","回言三省，若到官时，先且捉亲邻，唤问凶身。","君不认，遭打讯，你怎禁？急早商量，莫待祸生。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1894","tags":[]},{"id":"poem-0499869ae65e19a019819d0a","title":"留别舍弟","author":"王建","dynasty":"唐","verses":["孤贱相长育，未曾为远游。","谁不重欢爱，晨昏阙珍羞。","出门念衣车，草木当穷秋。","非疾有忧叹，实为人子尤。","世情本难合，对面隔山丘。","况复干戈地，儒夫何所投。","与尔俱长成，尚为沟壑忧。","岂非轻岁月，少小不勤修。","从今解思量，勉力谋善猷。","但得成尔身，衣食宁我求。","固合受此训，堕慢为身羞。","岁暮当归来，慎莫怀远游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c0f1e9a8-8f81-4001-9a1d-3fbe51e29e89","tags":[]},{"id":"poem-049cff285c9ad55191687b39","title":"和刘驾博士赠庄严律禅师","author":"李洞","dynasty":"唐","verses":["人言紫绶有光辉，不二心观似草衣。","尘劫自营还自坏，禅门无住亦无归。","松根穴蚁通山远，塔顶巢禽见海微。","每话南游偏起念，五峰波上入船扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-72c6bbb1-6ff5-43ee-b640-14f107c6275e","tags":[]},{"id":"poem-049f13c6a6ddb618b24d8f8e","title":"郊庙歌辞 中宗祀昊天乐章 舒和","author":"不详","dynasty":"唐","verses":["已陈粢盛敷严祀，更奏笙镛协雅声。","璇图宝历欣宁谧，晏俗淳风乐太平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c19f1e4c-2b6f-44cf-8ee2-0993f3ef2cf7","tags":[]},{"id":"poem-04a526fecf8c09810d3330e1","title":"九怀·陶壅","author":"王褒","dynasty":"汉","verses":["览杳杳兮世惟，余惆怅兮何归。","伤时俗兮溷乱，将奋翼兮高飞。","驾八龙兮连蜷，建虹旌兮威夷。","观中宇兮浩浩，纷翼翼兮上跻。","浮溺水兮舒光，淹低佪兮京沶。","屯余车兮索友，睹皇公兮问师。","道莫贵兮归真，羡余术兮可夷。","吾乃逝兮南娭，道幽路兮九疑。","越炎火兮万里，过万首兮嶷嶷。","济江海兮蝉蜕，绝北梁兮永辞。","浮云郁兮昼昏，霾土忽兮塺々。","息阳城兮广夏，衰色罔兮中怠。","意晓阳兮燎寤，乃自诊兮在兹。","思尧舜兮袭兴，幸咎繇兮获谋。","悲九州兮靡君，抚轼叹兮作诗。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-45","tags":[]},{"id":"poem-04b45f5c74d9573f2b3cd083","title":"江行无题一百首 八十五","author":"钱珝","dynasty":"唐","verses":["兴闲停桂楫，路好过松门。","不负佳山水，还开酒一樽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8b422a81-48ce-4768-9d6a-084896d74cff","tags":[]},{"id":"poem-04b74f148c998ed7fc8e03b3","title":"梦江南·楼上寝","author":"皇甫松","dynasty":"唐","verses":["楼上寝，残月下帘旌。","梦见秣陵惆怅事，桃花柳絮满江城，双髻坐吹笙。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-25","tags":[]},{"id":"poem-04c2406c66e71a42c3a5b2dd","title":"送从叔校书简南归","author":"孟郊","dynasty":"唐","verses":["长安别离道，宛在东南隅。","寒草根未死，愁人心已枯。","促促水上景，遥遥天际途。","生随昏晓中，皆被日月驱。","北骑达山岳，南帆指江湖。","高踪一超越，千里在须臾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ed947732-ca9c-4b2b-b96a-6c917796caba","tags":[]},{"id":"poem-04c59db118c9214fcf797586","title":"赋得送轩辕先生归罗浮山","author":"李洞","dynasty":"唐","verses":["旧山归隐浪摇青，绿鬓山童一帙经。","诗帖布帆猿鸟看，药煎金鼎鬼神听。","洞深头上聆仙语，船静鼻中闻海腥。","此处先生应不住，吾君南望漫劳形。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a36c47a8-15ee-41bc-8593-8b7887144bce","tags":[]},{"id":"poem-04cc178e897a16927042b913","title":"铜雀瓦","author":"赵文","dynasty":"宋","verses":["曹公筑铜台，气力雄九有。","咿嘤到香履，千古开笑口。","犹余当时瓦，作砚传不朽。","涪翁所珍惜，又复落吾手。","鬼夺与客偷，任运不汝守。","可怜台上人，不如此瓦寿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e76aba59-32b1-4d87-9e2a-8d85a0fe5b7c","tags":[]},{"id":"poem-04cfdd7d63f82ba3a39fed61","title":"六么令","author":"施惠《幽闺记》","dynasty":"元","verses":["(外、末、净、丑上)官司遍榜，捕捉陀满兴福恶党，正身拿住受官赏。","寻踪迹，问行藏，俺待见了，休想轻轻饶放。","俺待见了，休想轻轻饶放。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2881","tags":[]},{"id":"poem-04d86ed69e43a2e448e8b608","title":"相和歌辞 从军行","author":"李颀","dynasty":"唐","verses":["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野营万里无城郭，雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲萄入汉家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0ed53ef4-30ca-41ac-a629-d778e5cc2bfa","tags":["生活","冬天","唐诗三百首","乐府","边塞","相和歌辞"]},{"id":"poem-04e01981432247cd0af50387","title":"寓西马塍","author":"宋伯仁","dynasty":"宋","verses":["十亩荒林屋数间，门通小艇水湾湾。","人行远路多嫌僻，我得安居却称闲。","樽酒相忘霜后菊，一诗难尽雨中山。","何时漾下浮名事，只与田翁剩往还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-43304ffa-0126-44bb-8c8a-f261235c550d","tags":[]},{"id":"poem-04e8c23c763ce1130aca5dae","title":"永明山居诗（六十九首） 三十二","author":"延寿","dynasty":"唐","verses":["万事从来祇自招，安危由己路非遥。","笙歌韵里花先落，松桧枝间云未消。","数下磬声孤月夜，一炉香翥白云朝。","谁人会我高栖意，门掩空庭思寂寥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2611200b-6e89-4d9c-bee9-f3f2ac485698","tags":[]},{"id":"poem-04e8ef32c61bea5076df26bd","title":"台州郡治十二诗太守尤延之命赋 清平阁","author":"林宪","dynasty":"宋","verses":["饮浊斯贵清，路险斯贵平。","明明古君子，日用无非诚。","寒潭寒彻底，坦道安无倾。","日用傥如此，政化天与成。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2af1dc74-1995-4a5e-8585-a24e81ad6d68","tags":[]},{"id":"poem-04edf68e59b3f212b44e4fde","title":"解三酲","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["叹双亲把儿指望，教儿读古老文章。","比我会读书的到把亲撇漾，少甚么不识字的到得终养。","书，我只为你其中自有黄金屋，却教我撇却椿庭萱草堂。","还思想，休休，毕竟是文章误我，我误爹娘。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5218","tags":[]},{"id":"poem-04ee444f87424407758bf1fd","title":"瑞鹤仙·暖烟笼细柳","author":"周邦彦","dynasty":"宋","verses":["暖烟笼细柳。","弄万缕千丝，年年春色。","晴风荡无际，浓于酒、偏醉情人调客。","阑干倚处，度花香、微散酒力。","对重门半掩，黄昏淡月，院宇深寂。","愁极。","因思前事，洞房佳宴，正值寒食。","寻芳遍赏，金谷里，铜驼陌。","到而今、鱼雁沈沈无信，天涯常是泪滴。","早归来，云馆深处，那人正忆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-530","tags":[]},{"id":"poem-04f16e961027086a1e933d1e","title":"项王庙","author":"华镇","dynasty":"宋","verses":["刘氏功名未足多，谩将带砺指山河。","楚宫一夜虽虚垒，汉殿百年还艺禾。","今日祠堂皆寂寞，当时江水自逶迤。","有灵若忆生前事，应悔初为盖世歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-ee8019b5-f5e8-4586-99b1-781b42bddf0c","tags":[]},{"id":"poem-04f1a7fe7de21061576916cd","title":"朱湖","author":"赵文","dynasty":"宋","verses":["高低榉柳绿如苔，三两柴门傍竹开。","此处定无人挟弹，青青乳燕出溪来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-94498185-68c6-41fa-a608-212e6823c1f1","tags":[]},{"id":"poem-04f5f1c6f3c268b444f53b1b","title":"如梦令·纤月黄昏庭院","author":"纳兰性德","dynasty":"清","verses":["纤月黄昏庭院，语密翻教醉浅。","知否那人心。","旧恨新欢相半。","谁见。","谁见。","珊枕泪痕红泫。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-30","tags":[]},{"id":"poem-04fcbd94475270fe284de725","title":"对月了残经赞  其二","author":"释了惠","dynasty":"宋","verses":["麻线贯竹针，太阳相对面。","通身破绽多，如何补得遍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-fa9f0daf-abee-4070-9866-6736008fc591","tags":[]},{"id":"poem-04ffc6bd9321bb8bc8c59457","title":"有诏举贤良方正作诗勉钱申伯使继世科","author":"李纲","dynasty":"宋","verses":["中兴天子开贤科，笼络英俊归网罗。","此科久废习者少，应诏正恐人未多。","君家三世五制举，名与嵩华争嵯峨。","玉堂金马皆故物，髙文大策垂不磨。","今君落笔妙天下，该洽辩愽如悬河。","胡不进卷对廷策，清芬远绍扬其波。","勒兵小试见家法，坐却勍敌挥雕戈。","君如有意作大将，我愿荐信同萧何。","功名晚达未为老，志气方壮靡有他。","勉哉努力为门户，慎勿自弃成蹉跎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8892ee46-024c-4e4b-bc46-470464306502","tags":[]},{"id":"poem-0500b22631c0ab1bb7f0c71b","title":"相见欢·林花谢了春红","author":"李煜","dynasty":"五代","verses":["林花谢了春红，太匆匆！","无奈朝来寒雨晚来风。","胭脂泪，留人醉，几时重？","自是人生长恨水长东！"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-16","tags":[]},{"id":"poem-0508c8f997aa4596f3580701","title":"蜀道后期","author":"张说","dynasty":"唐","verses":["客心争日月，来往预期程。","秋风不相待，先至洛阳城。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-蜀道後期","tags":[]},{"id":"poem-0508d19964c8ac658a2925d6","title":"送宫人入道","author":"项斯","dynasty":"唐","verses":["愿随仙女董双成，王母前头作伴行。","初戴玉冠多悮拜，欲辞金殿别称名。","将敲碧落新斋磬，却进昭阳旧赐筝。","旦暮焚香绕坛上，步虚犹作按歌声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-cce85db9-5233-452c-a542-cb2dfe3b4187","tags":[]},{"id":"poem-05101d3a3824062231ec4196","title":"临江仙·寒柳","author":"纳兰性德","dynasty":"清","verses":["飞絮飞花何处是，层冰积雪摧残，疏疏一树五更寒。","爱他明月好，憔悴也相关。","最是繁丝摇落后，转教人忆春山。","湔裙梦断续应难。","西风多少恨，吹不散眉弯。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-95","tags":[]},{"id":"poem-051c59ab73419f0207251a1d","title":"猛虎行","author":"李贺","dynasty":"唐","verses":["长戈莫舂，长弩莫抨。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0422e408-0484-40d0-b826-da8e2c947490","tags":["泰山"]},{"id":"poem-0529b0b0cdeea3c4812883e9","title":"春秋战国门 赵宣子","author":"周昙","dynasty":"唐","verses":["门人曾不有提弥，连嗾呀呀孰敢支。","临难若教无苟免，乱朝争那以獒为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b523f030-bfc3-4034-9dd2-578816935a36","tags":[]},{"id":"poem-052ab0fea2bff69a2038e2e1","title":"咏史","author":"高适","dynasty":"唐","verses":["尚有绨袍赠，应怜范叔寒。","不知天下士，犹作布衣看。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-詠史","tags":[]},{"id":"poem-052bb8da39ff47bf18ef5ee8","title":"送李潜归绵州觐省","author":"姚鹄","dynasty":"唐","verses":["朱楼对翠微，红斾出重扉。","此地千人望，寥天一鹤归。","雪封山崦白，鸟拂栈梁飞。","谁比趋庭恋，骊珠耀彩衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0b3df43d-b443-466e-8850-b800c99ec211","tags":[]},{"id":"poem-0535479a196cfed4d8f64e75","title":"游仙词三十三首  其二七","author":"王镃","dynasty":"宋","verses":["飞佩乘风海上游，麟洲有路透炎州。","仙人养就千年鼠，时采长毛织火裘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-bc6477e3-496d-44f4-9c07-54f34a39d4bb","tags":[]},{"id":"poem-054ee22d9cb0d5fd2ec8004a","title":"高楼望月","author":"纳兰性德","dynasty":"清","verses":["戚戚复戚戚，高楼月如雪。","二八正婵娟，月明翡翠钿。","由来工织锦，生小倚朱弦。","朱弦岂解愁，素手似云浮。","一声落天上，闻者皆泪流。","别郎已经年，望郎出楼前。","青天如海水，碧月如珠圆。","月圆以复缺，不见长安客。","古道白于霜，沙灭行人迹。","月出光在天，月高光在地。","何当同心人，两两不相弃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-220","tags":[]},{"id":"poem-054efc5d83bd8a853decc0c4","title":"猿","author":"曹松","dynasty":"唐","verses":["曾宿三巴路，今来不愿听。","云根啼片白，峰顶掷尖青。","护果憎禽啄，栖霜觑叶零。","唯应卧岚客，怜尔傍嵒扃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6cf5fdd1-ff56-4375-b5c9-9ddb33684b1c","tags":[]},{"id":"poem-054f1e01a300391a616edf44","title":"虞美人·秋夕信步","author":"纳兰性德","dynasty":"清","verses":["愁痕满地无人省，露湿琅玕影。","闲阶小立倍荒凉。","还剩旧时月色在潇湘。","薄情转是多情累，曲曲柔肠碎。","红笺向壁字模糊，忆共灯前呵手为伊书。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-202","tags":[]},{"id":"poem-05523c18d529fa94f899ca67","title":"瑶池","author":"李商隐","dynasty":"唐","verses":["瑶池阿母绮窗开，黄竹歌声动地哀。","八骏日行三万里，穆王何事不重来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2161a569-6250-4886-9500-2168821b62be","tags":["唐诗三百首","七言绝句","神话","讽刺"]},{"id":"poem-0552f91679ceb30041d540c2","title":"踏莎行·候馆梅残","author":"欧阳修","dynasty":"宋","verses":["候馆梅残，溪桥柳细。","草熏风暖摇征辔。","离愁渐远渐无穷，迢迢不断如春水。","寸寸柔肠，盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，行人更在春山外。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-171","tags":["宋词三百首"]},{"id":"poem-0560d7e885811cfb32f1b371","title":"和张文裕初寒十首  其二","author":"司马光","dynasty":"宋","verses":["何处初寒好，初寒洛汭宫。","翠华虽脉脉，佳气自葱葱。","阙角月华白，苑墙霜叶红。","都人心望幸，注目不离东。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-55638285-eaf3-4f0a-8dc4-b3862c4a7a28","tags":[]},{"id":"poem-05631702e249a0fd96f19ec5","title":"减字木兰花·使君那里","author":"黄庭坚","dynasty":"宋","verses":["使君那里。","千骑尘中依约是。","拂我眉头。","无处重寻庾信愁。","山云弥漫。","夹道旌旗联复断。","万事茫茫。","分付澄波与烂肠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-676","tags":[]},{"id":"poem-056c5b018a908bf0aabd9293","title":"鱼藻","author":"佚名","dynasty":"先秦","verses":["鱼在在藻，有颁其首。王在在镐，岂乐饮酒。","鱼在在藻，有莘其尾。王在在镐，饮酒乐岂。","鱼在在藻，依于其蒲。王在在镐，有那其居。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-220","tags":[]},{"id":"poem-056d57c3888fce4a6fd40de7","title":"述怀  其二","author":"王镃","dynasty":"宋","verses":["心如冰静已无波，劫世虚言莫问他。","老眼易昏书字大，醉言难谨忤人多。","山厨烟火烧红叶，水国衣裳制绿蓑。","浊富清贫分两路，高眠不管吏征科。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-336aef0c-8b15-4a45-b4d7-01237ac390ec","tags":[]},{"id":"poem-056f0bb69faf36f7c6d58c60","title":"送赵素轩去婺守为本道仓使","author":"王柏","dynasty":"宋","verses":["人物干淳旧典型，满腔全是远庵仁。","来时懒作三刀梦，去日留为一道春。","千里桑麻深雨露，双溪风月更精神。","出门父老欢迎处，犹有文公旧郡民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-53c9e3c0-dd30-4a76-a146-bd6c2d8143cf","tags":[]},{"id":"poem-0574fdb2a8a0aaba1eb51fc4","title":"中秋宿邓逸人居","author":"刘得仁","dynasty":"唐","verses":["偶与山僧宿，吟诗坐到明。","夜凉耽月色，秋渴漱泉声。","磵木如竿耸，窗云作片生。","白衣闲自贵，不揖汉公卿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d446a0c0-81f4-42df-ab74-26a4575dd893","tags":[]},{"id":"poem-0575621a4a5dd095bd42f9f5","title":"吊江南老家人春梅","author":"孟郊","dynasty":"唐","verses":["念尔筋力尽，违我衣食恩。","奈何粗犷儿，生鞭见死痕。","旧使常以礼，新怨将谁吞。","胡为乎泥中，消歇教义源。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b4ab0057-6846-46fc-afce-1d641980509f","tags":[]},{"id":"poem-0576d04d6eaec3aab2797a34","title":"番鼓儿","author":"施惠《幽闺记》","dynasty":"元","verses":["(净)为塞北。","为塞北，兴兵临边鄙。","但州城关津险隘，势怎当敌？待欲迁都回避。","不许稽迟，上京去缉探事实。","(合)火速便驰驿，等回音星飞电急。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2902","tags":[]},{"id":"poem-0577def5059fc8e3fbb4dd4d","title":"别离情所钟十二章章四句送定叟弟之官严陵  其六","author":"张栻","dynasty":"宋","verses":["巍巍孤高亭，念我昔所喟。","子也时一登，千载起立志。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-db7d6818-0741-4928-a1a4-f52d7ac029f2","tags":[]},{"id":"poem-0583aa910f9250ff9edac1a5","title":"天问","author":"屈原","dynasty":"先秦","verses":["曰：遂古之初，谁传道之？","上下未形，何由考之？","冥昭瞢暗，谁能极之？","冯翼惟象，何以识之？","明明暗暗，惟时何为？","阴阳三合，何本何化？","圜则九重，孰营度之？","惟兹何功，孰初作之？","斡维焉系，天极焉加？","八柱何当，东南何亏？","九天之际，安放安属？","隅隈多有，谁知其数？","天何所沓？","十二焉分？","日月安属？","列星安陈？","出自汤谷，次于蒙汜。","自明及晦，所行几里？","夜光何德，死则又育？","厥利维何，而顾菟在腹？","女岐无合，夫焉取九子？","伯强何处？","惠气安在？","何阖而晦？","何开而明？","角宿未旦，曜灵安藏？","不任汩鸿，师何以尚之？","佥曰。","“何忧，何不课而行之？”","鸱龟曳衔，鲧何听焉？","顺欲成功，帝何刑焉？","永遏在羽山，夫何三年不施？","伯禹愎鲧，夫何以变化？","纂就前绪，遂成考功。","何续初继业，而厥谋不同？","洪泉极深，何以窴之？","地方九则，何以坟之？","河海应龙？","何尽何历？","鲧何所营？","禹何所成？","康回冯怒，墬何故以东南倾？","九州安错？","川谷何洿？","东流不溢，孰知其故？","东西南北，其修孰多？","南北顺椭，其衍几何？","昆仑悬圃，其尻安在？","增城九重，其高几里？","四方之门，其谁从焉？","西北辟启，何气通焉？","日安不到？","烛龙何照？","羲和之未扬，若华何光？","何所冬暖？","何所夏寒？","焉有石林？","何兽能言？","焉有虬龙，负熊以游？","雄虺九首，鯈忽焉在？","何所不死？","长人何守？","靡蓱九衢，枲华安居？","灵蛇吞象，厥大何如？","黑水玄趾，三危安在？","延年不死，寿何所止？","鲮鱼何所？","鬿堆焉处？","羿焉彃日？","乌焉解羽？","禹之力献功，降省下土四方。","焉得彼嵞山女，而通之于台桑？","闵妃匹合，厥身是继。","胡维嗜不同味，而快鼌饱？","启代益作后，卒然离蠥。","何启惟忧，而能拘是达？","皆归射鞫，而无害厥躬。","何后益作革，而禹播降？","启棘宾商，《九辨》《九歌》。","何勤子屠母，而死分竟地？","帝降夷羿，革孽夏民。","胡射夫河伯，而妻彼雒嫔？","冯珧利决，封豨是射。","何献蒸肉之膏，而后帝不若？","浞娶纯狐，眩妻爰谋。","何羿之射革，而交吞揆之？","阻穷西征，岩何越焉？","化而为黄熊，巫何活焉？","咸播秬黍，莆雚是营。","何由并投，而鲧疾修盈？","白蜺婴茀，胡为此堂？","安得夫良药，不能固臧？","天式从横，阳离爰死。","大鸟何鸣，夫焉丧厥体？","蓱号起雨，何以兴之？","撰体协胁，鹿何膺之？","鳌戴山抃，何以安之？","释舟陵行，何之迁之？","惟浇在户，何求于嫂？","何少康逐犬，而颠陨厥首？","女歧缝裳，而馆同爰止。","何颠易厥首，而亲以逢殆？","汤谋易旅，何以厚之？","覆舟斟寻，何道取之？","桀伐蒙山，何所得焉？","妺嬉何肆，汤何殛焉？","舜闵在家，父何以鳏？","尧不姚告，二女何亲？","厥萌在初，何所亿焉？","璜台十成，谁所极焉？","登立为帝，孰道尚之？","女娲有体，孰制匠之？","舜服厥弟，终然为害。","何肆犬豕，而厥身不危败？","吴获迄古，南岳是止。","孰期去斯，得两男子？","缘鹄饰玉，后帝是飨。","何承谋夏桀，终以灭丧？","帝乃降观，下逢伊挚。","何条放致罚，而黎服大说？","简狄在台，喾何宜？","玄鸟致贻，女何喜？","该秉季德，厥父是臧。","胡终弊于有扈，牧夫牛羊？","干协时舞，何以怀之？","平胁曼肤，何以肥之？","有扈牧竖，云何而逢？","击床先出，其命何从？","恒秉季德，焉得夫朴牛？","何往营班禄，不但还来？","昏微循迹，有狄不宁。","何繁鸟萃棘，负子肆情？","眩弟并淫，危害厥兄。","何变化以作诈，而后嗣逢长？","成汤东巡，有莘爰极。","何乞彼小臣，而吉妃是得？","水滨之木，得彼小子。","夫何恶之，媵有莘之妇？","汤出重泉，夫何辠尤？","不胜心伐帝，夫谁使挑之？","会朝争盟，何践吾期？","苍鸟群飞，孰使萃之？","列击纣躬，叔旦不嘉。","何亲揆发足，周之命以咨嗟？","授殷天下，其位安施？","反成乃亡，其罪伊何？","争遣伐器，何以行之？","并驱击翼，何以将之？","昭后成游，南土爰底。","厥利惟何，逢彼白雉？","穆王巧梅，夫何为周流？","环理天下，夫何索求？","妖夫曳炫，何号于市？","周幽谁诛？","焉得夫褒姒？","天命反侧，何罚何佑？","齐桓九会，卒然身杀。","彼王纣之躬，孰使乱惑？","何恶辅弼，谗谄是服？","比干何逆，而抑沈之？","雷开阿顺，而赐封之？","何圣人之一德，卒其异方？","梅伯受醢，箕子详狂？","稷维元子，帝何竺之？","投之于冰上，鸟何燠之？","何冯弓挟矢，殊能将之？","既惊帝切激，何逢长之？","伯昌号衰，秉鞭作牧。","何令彻彼岐社，命有殷国？","迁藏就岐，何能依？","殷有惑妇，何所讥？","受赐兹醢，西伯上告。","何亲就上帝罚，殷之命以不救？","师望在肆，昌何识？","鼓刀扬声，后何喜？","武发杀殷，何所悒？","载尸集战，何所急？","伯林雉经，维其何故？","何感天抑墬，夫谁畏惧？","皇天集命，惟何戒之？","受礼天下，又使至代之？","初汤臣挚，后兹承辅。","何卒官汤，尊食宗绪？","勋阖梦生，少离散亡。","何壮武历，能流厥严？","彭铿斟雉，帝何飨？","受寿永多，夫何久长？","中央共牧，后何怒？","蜂蛾微命，力何固？","惊女采薇，鹿何佑？","北至回水，萃何喜？","兄有噬犬，弟何欲？","易之以百两，卒无禄？","薄暮雷电，归何忧？","厥严不奉，帝何求？","伏匿穴处，爰何云？","荆勋作师，夫何长？","悟过改更，我又何言？","吴光争国，久余是胜。","何环穿自闾社丘陵，爰出子文？","吾告堵敖以不长。","何试上自予，忠名弥彰？"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-12","tags":[]},{"id":"poem-05877207438791998242885e","title":"柳含烟·隋堤柳","author":"毛文锡","dynasty":"五代","verses":["隋堤柳，汴河旁。","夹岸绿阴千里，龙舟凤舸木兰香，锦帆张。","因梦江南春景好，一路流苏羽葆。","笙歌未尽起横流，锁春愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-17","tags":[]},{"id":"poem-058ceaa2124ca79a961f687a","title":"郊庙歌辞 祀九宫贵神乐章 舒和","author":"不详","dynasty":"唐","verses":["羽籥既阕干戚陈，八音克谐六变新。","愉贵神兮般以乐，保皇祚兮万斯春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a7cca728-ddd3-41a8-b38b-a29a3bfd6ab9","tags":[]},{"id":"poem-05914f23e60f1ec2672991fa","title":"清平乐·赵家燕燕","author":"曹勋","dynasty":"宋","verses":["赵家燕燕。","宜在昭阳殿。","春入馆娃深宫宴。","秀色从来未见。","浅颦轻笑都宜。","临风好是腰肢。","今夜松江归路，月明愁满清辉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-200","tags":[]},{"id":"poem-059a2f41dfde27e48dd49c83","title":"思园春","author":"无名氏《张协状元》","dynasty":"元","verses":["你要休时我未休。","(净)早来吾殿下吃猪头。","(旦出)灵杯不许后，教我怎生留！(生)漾人葫芦水上游，葫芦儿沉后我共伊休。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2543","tags":[]},{"id":"poem-059ef85ef8bc2eb1e0316354","title":"兴国璨老浴堂新成以伽佗见示戏成三绝句  其三","author":"李纲","dynasty":"宋","verses":["池中已具八功德，浴处还敷七浄华。","妙体本来尘不染，何妨痒处与抓爬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f93be522-e767-4928-8d86-7fe8c7be080b","tags":[]},{"id":"poem-05b446cf640b82a5349cc062","title":"张大年览文与可墨竹及先人所题与可挽诗见惠长句因次其韵","author":"刘跂","dynasty":"宋","verses":["墨妙苍筤双玉枝，赏音悲壮七哀诗。","多惭寂寞青毡地，又得风流黄绢词。","往事白杨无数拱，余生衰鬓不堪垂。","声沈影绝何人识，頼有柯亭可见思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c34e31ca-60b3-4d49-98f9-30be9b215d59","tags":[]},{"id":"poem-05bd8087a51cda744cd245a4","title":"赠梅处士","author":"张籍","dynasty":"唐","verses":["早闻声价满京城，头白江湖放旷情。","讲易自传新注义，题诗不著旧官名。","近移马迹山前住，多向牛头寺里行。","天子如今议封禅，应将束帛请先生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c637d249-8158-48b9-98ee-a2300c0acbde","tags":[]},{"id":"poem-05becbdf8b775664e618b2fe","title":"偶然五首 一","author":"皎然","dynasty":"唐","verses":["乐禅心似荡，吾道不相妨。","独悟歌还笑，谁言老更狂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5a1757d3-f95c-47b3-9951-523538ecd61e","tags":[]},{"id":"poem-05c16d5e2ffc13632fbd4430","title":"苏幕遮·碧云天","author":"范仲淹","dynasty":"宋","verses":["碧云天，黄叶地。","秋色连波，波上寒烟翠。","山映斜阳天接水。","芳草无情，更在斜阳外。","黯乡魂，追旅思。","夜夜除非，好梦留人睡。","明月楼高休独倚。","酒入愁肠，化作相思泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-139","tags":["宋词三百首"]},{"id":"poem-05c42350cbc3037b600b8521","title":"宋中十首 八","author":"高适","dynasty":"唐","verses":["五霸递征伐，宋人无战功。","解围幸奇说，易子伤吾衷。","唯见卢门外，萧条多转蓬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-88b7713b-419a-4972-9174-3418204f1e09","tags":[]},{"id":"poem-05ccdda6797ef75ab4ba87fe","title":"小游仙诗九十八首 二","author":"曹唐","dynasty":"唐","verses":["上元元日豁明堂，五帝望空拜玉皇。","万树琪花千圃药，心知不敢辄形相。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9baeafdd-69f2-46c2-933a-8ce96b2502cc","tags":[]},{"id":"poem-05d4b2460a7d1a048995780e","title":"闲居","author":"释延寿","dynasty":"宋","verses":["闲居谁似我，退迹理难过。","要势危身早，浮荣败德多。","雨催虫出穴，寒逼鸟移窠。","野迳无人翦，疏窗入薜萝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-8026338a-472e-405a-a820-f9faacb60a61","tags":[]},{"id":"poem-05eb56d262cf501cf78d2603","title":"贫女","author":"李山甫","dynasty":"唐","verses":["平生不识绣衣裳，闲把荆钗亦自伤。","镜里只应谙素貌，人间多自信红妆。","当年未嫁还忧老，终日求媒即道狂。","两意定知无说处，暗垂珠泪湿蚕筐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e3ae9671-6997-446b-96dc-3fd66939e152","tags":[]},{"id":"poem-05ed42929db5cc1bf5f4423c","title":"又绝句寄题毗陵驿","author":"徐铉","dynasty":"宋","verses":["曾持使节驻毗陵，长与州人有旧情。","为向驿桥风月道，舍人髭鬓白千茎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-cac7a89b-e5c9-40ef-bbca-b21094881d2b","tags":[]},{"id":"poem-05ee8168e01c837a7691df37","title":"因僧问话有颂（二首） 一","author":"延沼","dynasty":"唐","verses":["万法虚无实际深，凝然妄肯绝踈亲。","断常妙理修途者，镜像宜扶觉照频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6d732852-e1e4-4585-b494-13596a9f6b8e","tags":[]},{"id":"poem-05f3e00dd405492c4c07c301","title":"得遇入京（伯三八一二）","author":"刘长卿","dynasty":"唐","verses":["万里南来喜复悲，生涯何幸有归期。","空庭叶散风摇落，旧邑人疏经乱离。","巴路千山秋水在，江花独树夕阳微。","为君一话此中事，白首长沙知不知？","（按《全唐诗》内长卿诗卷五与刘随州集卷九〖四部丛刊本〗都有这首诗，题为「自江西归至旧任官舍赠袁赞府自经刘展平后」，但文句异同甚多，故破格载入，兼录集本如下：「却见同官喜后悲，此生何幸有归期。","空庭客至逢摇落，旧邑人稀经乱离。","湘路来过回雁处，江城卧听捣衣时。","南方风土劳君问，贾谊长沙岂不知。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6293174f-62cc-485b-b983-4676e47cedfd","tags":[]},{"id":"poem-05f3e16e924b4a2d246f2522","title":"菩萨蛮·过张见阳山居，赋赠","author":"纳兰性德","dynasty":"清","verses":["车尘马迹纷如织，羡君筑处真幽僻。","柿叶一林红，萧萧四面风。","功名应看镜，明月秋河影。","安得此山间，与君高卧闲。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-183","tags":[]},{"id":"poem-05faf48af9a4a48b847a0106","title":"清平乐·风鬟雨鬓","author":"纳兰性德","dynasty":"清","verses":["风鬟雨鬓，偏是来无准。","倦倚玉兰看月晕，容易语低香近。","软风吹遍窗纱，心期便隔天涯。","从此伤春伤别，黄昏只对梨花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-161","tags":[]},{"id":"poem-05fc0770ca25beaca969f036","title":"郊庙歌辞 祭[太]社乐章 舒和","author":"褚亮","dynasty":"唐","verses":["神道发生敷九稼，阴极乘仁畅八埏。","纬武经文隆景化，登祥荐祉启丰年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3ea3afb2-2d7f-49c2-86d7-f7bc456a95b0","tags":[]},{"id":"poem-05fe2889ca1805b9592b345f","title":"秋夜听捣衣","author":"杨凝","dynasty":"唐","verses":["砧杵闻秋夜，裁缝寄远方。","声微渐湿露，响细未经霜。","兰牖唯遮树，风帘不碍凉。","云中望何处，听此断人肠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-11c4239f-8784-43e5-87a7-3c2d2109dd22","tags":[]},{"id":"poem-0600f08022c0870eebc5fefc","title":"长安退将","author":"项斯","dynasty":"唐","verses":["塞外冲沙损眼明，归来养病住秦京。","上高楼阁看星坐，著白衣裳把劒行。","常说老身思鬬将，最悲无力制蕃营。","翠眉红脸和回鹘，惆怅中原不用兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e29cad57-2131-4c70-a665-685a81ce8286","tags":[]},{"id":"poem-06026c4cea0bf777eb66f289","title":"贻钓鱼李处士","author":"谭用之","dynasty":"宋","verses":["罢吟鹦鹉草芊芊，又泛鸳鸯水上天。","一棹冷涵杨柳雨，片帆香挂芰荷烟。","绿摇江澹萍离岸，红点云疏橘满川。","何处邈将归画府，数茎红蓼一渔船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-24ec8820-09ca-4a5f-aac5-98424d27bfc8","tags":[]},{"id":"poem-0602848e9bac4b240820ada5","title":"忆江西幷悼亡友","author":"曹松","dynasty":"唐","verses":["前心奈兵阻，悔作豫章分。","芳草未归日，故人多是坟。","帆行出岫雨，马践过江云。","此地一罇酒，当时皆以文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ff2789f2-da3b-47e1-803b-a1f9840a5516","tags":[]},{"id":"poem-0605d9fcc0a3249e63138cc2","title":"减字浣溪沙・浣溪沙·莲烛啼痕怨漏长","author":"贺铸","dynasty":"宋","verses":["莲烛啼痕怨漏长。","吟蛩随月到回廊。","一屏烟景画潇湘。","连夜断无行雨梦，隔年犹有著人香。","此情须信是难忘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-118","tags":[]},{"id":"poem-060c8fceb59fa6f9f2775086","title":"读刘得仁贾岛集二首 二","author":"贯休","dynasty":"唐","verses":["役思曾冲尹，多言阻国亲。","桂枝何所直，陋巷不胜贫。","马病唯汤雪，门荒劣有人。","伊余吟亦苦，为尔一眉嚬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-001a7fb3-c61b-42aa-82bc-28d470be9b08","tags":[]},{"id":"poem-060fc6cca7491cdc37bf1b25","title":"过剡  其一","author":"释居简","dynasty":"宋","verses":["曹娥泪血点江潮，百里都无绿半篙。","剡水迎潮须款曲，小分清莹洗浑涛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-55018551-bab5-47f9-b724-ddaa6bba0b94","tags":[]},{"id":"poem-061218f660ea6ca204864c43","title":"小游仙诗九十八首 三十五","author":"曹唐","dynasty":"唐","verses":["紫羽麾幢下玉京，却邀真母入三清。","白龙久住浑相恋，斜倚祥云不肯行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-58d58863-d49f-4f1a-b79f-d21204c5e8bd","tags":[]},{"id":"poem-061222a8a4f1307873b898b9","title":"巫山高二首 一","author":"沈佺期","dynasty":"唐","verses":["巫山峰十二，合沓隐昭回。","俯眺琵琶峡，平看云雨台。","古槎天外倚，瀑水日边来。","何忍猿啼夜，荆王枕席开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f5a94e24-96f3-4645-a628-3ea2359b872d","tags":[]},{"id":"poem-0615da7a019a6b996f9fa31a","title":"满庭芳·雪底寻梅","author":"沈蔚","dynasty":"宋","verses":["雪底寻梅，冰痕观水，晚来天气尤寒。","渐闻歌笑，轻暖发春妍。","赏尽十洲新景，依稀见、三岛风烟。","判深夜，一年月色，只是这般圆。","熙然。","千里地，何妨载酒，频上湖船。","况坐中高客，不日朝天。","须信人间好处，没个事、胜得尊前。","东风近，侵寻桃李，别做醉夤缘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-974","tags":[]},{"id":"poem-061cfa4ec386a4221ec56cb6","title":"十诗谢廖计使  其七","author":"陈造","dynasty":"宋","verses":["古今国士遇，揆我不尽无。","顽钟未容器，巧匠徒为模。","即今鹗书上，逮此鹤发余。","但恐良夜梦，翩翾只江湖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1ae7211c-0836-4d64-8a39-9497290ef4b0","tags":[]},{"id":"poem-0623c6783f1928209582cae2","title":"谒韩祠","author":"陈知柔","dynasty":"宋","verses":["斯文何罪窜南荒，来谒孤祠泪数行。","恐有遗书藏坏壁，岂无哀赋吊沅湘。","精神不受氛烟蔽，道义长涵日月光。","四壁萧萧香火冷，何人能与作堂皇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-af002946-e5fa-4bb7-8c64-ca7f5f0781c1","tags":[]},{"id":"poem-0625cfac0d52cc5d7ed06f16","title":"崧高","author":"佚名","dynasty":"先秦","verses":["崧高维岳，骏极于天。维岳降神，生甫及申。维申及甫，维周之翰。四国于蕃。四方于宣。","亹亹申伯，王缵之事。于邑于谢，南国是式。王命召伯，定申伯之宅。登是南邦，世执其功。","王命申伯，式是南邦。因是谢人，以作尔庸。王命召伯，彻申伯土田。王命傅御，迁其私人。","申伯之功，召伯是营。有俶其城，寝庙既成。既成藐藐，王锡申伯。四牡𫏋𫏋，钩膺濯濯。","王遣申伯，路车乘马。我图尔居，莫如南土。锡尔介圭，以作尔宝。往近王舅，南土是保。","申伯信迈，王饯于郿。申伯还南，谢于诚归。王命召伯，彻申伯土疆。以峙其粻，式遄其行。","申伯番番，既入于谢。徒御啴啴。周邦咸喜，戎有良翰。不显申伯，王之元舅，文武是宪。","申伯之德，柔惠且直。揉此万邦，闻于四国。吉甫作诵，其诗孔硕。其风四好，以赠申伯。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-258","tags":[]},{"id":"poem-0628b69e02112bb55f8d6aeb","title":"鹿鸣","author":"佚名","dynasty":"先秦","verses":["呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。吹笙鼓簧，承筐是将。人之好我，示我周行。","呦呦鹿鸣，食野之蒿。我有嘉宾，德音孔昭。视民不恌，君子是则是效。我有旨酒，嘉宾式燕以敖。","呦呦鹿鸣，食野之芩。我有嘉宾，鼓瑟鼓琴。鼓瑟鼓琴，和乐且湛。我有旨酒，以燕乐嘉宾之心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-160","tags":[]},{"id":"poem-062d80c1fcfe07dea5bb5076","title":"戏赠无本 一","author":"孟郊","dynasty":"唐","verses":["长安秋声干，木叶相号悲。","瘦僧卧冰凌，嘲咏含金痍。","金痍非战痕，峭病方在兹。","诗骨耸东野，诗涛涌退之。","有时踉跄行，人惊鹤阿师。","可惜李杜死，不见此狂痴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-22107002-3bdc-478c-a488-2aa99acc3f8b","tags":[]}];
